/* Page du jeu de cartes Galactik Cartes (générée depuis cartes.html, ne pas modifier à la main) */
window.TCG_PAGE = "<!doctype html>\n<html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Galactik Cartes</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Bagel+Fat+One&family=Montserrat:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n\n<style>\n/* Direction artistique reprise de Galactik Manager : fond marine dégradé vers le rouge, panneaux #181e2d bordés de gris-bleu,\n   boutons pilules, cartes portrait à bordure holographique, chiffres en Bagel Fat One. Thème unique sombre, comme le jeu. */\n:root{\n  --bg1:#181e2d; --bg2:#0f121d; --bg3:#270a10;\n  --panel:#181e2d; --deep:#0f121d; --bd:#747881; --bd2:#3a4157;\n  --tx:#eef1f8; --mu:#d3d9e6; --mu2:#9aa3b8;\n  --peri:#7789b8; --onac:#0b0f1a; --side:#35405e; --ac2:#e4338f;\n  --atk:#ff4fa3; --def:#33e0ff; --gold:#ffd23f; --ok:#46e08a; --bad:#e5484d; --vio:#9b6bff; --lime:#c8f560;\n  --pGK:#e0a526; --pDEF:#3b8fe8; --pMID:#2fb36b; --pATT:#e5484d;\n  --back:url('data:image/jpeg;base64,');\n  --tplatt:url('data:image/svg+xml;base64,');\n  --tpldef:url('data:image/svg+xml;base64,');\n  --tplmid:url('data:image/svg+xml;base64,');\n  --tplbut:url('data:image/svg+xml;base64,');\n  --wm3:url('data:image/svg+xml;base64,');\n  --wm2:url('data:image/svg+xml;base64,');\n  --wmo:url('data:image/webp;base64,');\n  --pkV:url('data:image/webp;base64,');\n  --pkN:url('data:image/webp;base64,');\n  --pkD:url('data:image/webp;base64,');\n  --tpltac:url('data:image/svg+xml;base64,');\n  --tplgk:url('data:image/svg+xml;base64,');\n  --holo:conic-gradient(from 40deg,#ff4fa3,#ffd23f,#46e08a,#33e0ff,#9b6bff,#ff4fa3);\n  --fd:'Bagel Fat One','Exo 2',system-ui,sans-serif;\n  --fb:'Montserrat',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;\n  --cw:clamp(50px,min(8.6vw,9.8vh),88px);\n  color-scheme:dark;\n}\n*{box-sizing:border-box}\nhtml,body{height:100%}\nbody{margin:0;color:var(--tx);font-family:var(--fb);background:var(--bg2);\n  background-image:linear-gradient(135deg,var(--bg1) 0%,var(--bg2) 55%,var(--bg2) 72%,var(--bg3) 100%);background-attachment:fixed;\n  padding-left:max(10px,env(safe-area-inset-left,0px));padding-right:max(10px,env(safe-area-inset-right,0px))}\nbutton{font-family:var(--fb);font-weight:800;cursor:pointer;border:2px solid var(--bd);border-radius:999px;padding:9px 18px;font-size:14px;color:var(--tx);background:var(--panel);transition:transform .12s,opacity .12s,background .12s}\nbutton:hover:not(:disabled){transform:translateY(-1px);border-color:var(--peri)}\nbutton:focus-visible{outline:3px solid var(--def);outline-offset:2px}\nbutton:disabled{opacity:.4;cursor:not-allowed}\nbutton.p,#bAct,#go,.row button:last-child{background:var(--peri);border-color:var(--peri);color:var(--onac)}\nbutton.ghost{background:var(--panel)}\n.app{max-width:1100px;margin:0 auto;display:flex;flex-direction:column;gap:6px;min-height:100%;padding-block:8px}\n\n/* barre du haut, comme la barre d'infos du jeu */\nheader{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:var(--side);border:2px solid var(--peri);border-radius:22px;padding:6px 10px}\nheader h1{font-family:var(--fb);font-weight:800;font-size:clamp(17px,2.6vw,22px);margin:0;display:flex;align-items:center;gap:8px;line-height:1}\nheader h1 .lg{width:30px;height:30px;border-radius:50%;background:var(--holo);display:grid;place-items:center;flex:none}\nheader h1 .lg i{width:24px;height:24px;border-radius:50%;background:var(--deep);display:grid;place-items:center;font-style:normal;font-family:var(--fd);font-size:11px;color:var(--tx)}\nheader h1 span{color:var(--mu2);font-weight:600}\n.score{display:flex;gap:6px;align-items:center;margin-left:auto;font-weight:700;font-size:13px}\n.score b{font-family:var(--fd);font-weight:400;font-size:20px;min-width:34px;text-align:center;padding:1px 10px;border-radius:999px;background:var(--panel);border:2px solid var(--bd)}\n.hbtn{display:flex;gap:6px;flex-wrap:wrap}\n.hbtn button{padding:6px 12px;font-size:12px}\n\n.side{display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:stretch;background:var(--panel);border:2px solid var(--bd);border-radius:20px;padding:8px}\n.side.me{border-color:var(--peri)}\n.col{display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center}\n.stk{display:flex;gap:6px}.stk .slot{width:calc(var(--cw)*.7)}\n.zl{font-size:10px;font-weight:700;letter-spacing:1px;color:var(--mu2);text-transform:uppercase;text-align:center}\n.slot{width:var(--cw);aspect-ratio:4/5;border:2px dashed var(--bd);border-radius:12px;display:flex;align-items:center;justify-content:center;position:relative;color:var(--mu2);font-family:var(--fd);font-size:18px}\n.goals{display:flex;gap:4px}\n.goals .slot{width:calc(var(--cw)*.62)}\n.goals .slot.on{border:0;border-radius:0;background:var(--tplbut) center/100% 100% no-repeat;font-size:0;color:transparent;filter:drop-shadow(0 3px 8px #000a)}\n.goals .slot.on.nw{animation:butin .5s cubic-bezier(.2,1.4,.4,1) backwards}\n@keyframes butin{from{transform:scale(.4) rotate(-8deg);opacity:0}}\n.stack{cursor:pointer}\n.stack.has{border:0;background:#fff;border-radius:10px;box-shadow:0 3px 10px #0007}\n.stack.has::before{content:\"\";position:absolute;inset:5%;border-radius:7%/5.6%;background:var(--back) center/cover no-repeat}\n.stack.has .n{position:relative;z-index:1;background:#0f121dcc;border-radius:999px;padding:0 8px;font-size:15px}\n.stack .n{font-family:var(--fd);font-size:17px;color:var(--tx)}\n.bench{background:var(--deep);border:2px solid var(--bd2);border-radius:16px;min-height:calc(var(--cw)*1.25 + 30px);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:6px;position:relative;min-width:0}\n.bench .cards{display:flex;gap:6px;flex-wrap:wrap;justify-content:center}\n.bench .tot{font-weight:700;font-size:14px;min-height:18px}\n.bench .tot b{font-family:var(--fd);font-weight:400;font-size:17px}\n.role{position:absolute;top:6px;left:8px;font-size:10px;font-weight:800;letter-spacing:1px;padding:3px 10px;border-radius:999px;text-transform:uppercase;color:#0b0f1a}\n.role.A{background:var(--atk)}.role.D{background:var(--def)}\n\n.mid{display:flex;align-items:center;justify-content:center;gap:12px;min-height:50px;text-align:center;flex-wrap:wrap;padding:4px 0}\n.msg{font-weight:700;font-size:clamp(13px,1.8vw,15px);max-width:62ch;text-wrap:balance;color:var(--mu)}\n.msg .big{font-family:var(--fd);font-weight:400;font-size:clamp(24px,4vw,36px);display:block;line-height:1.1;color:var(--tx)}\n.msg .big.goal{color:var(--atk)}.msg .big.block{color:var(--def)}.msg .big.gold{color:var(--gold)}\n\n.handbar{display:flex;align-items:flex-end;gap:10px;flex-wrap:wrap;justify-content:center;padding-bottom:6px}\n.hand{display:flex;gap:6px;justify-content:center;flex-wrap:wrap;min-height:calc(var(--cw)*1.25 + 14px);align-items:flex-end}\n.opp-hand{display:flex;gap:3px;align-items:center;justify-content:center}\n.opp-hand .card{width:24px}.opp-hand .card.back::after{font-size:8px}\n\n/* cartes : portrait du joueur, bordure holographique, chiffres Bagel */\n.card{width:var(--cw);aspect-ratio:4/5;border-radius:14px;position:relative;flex:none;background:var(--holo);padding:2px;\n  box-shadow:0 0 10px #9b6bff55;transition:transform .18s,box-shadow .18s;font-size:calc(var(--cw)*.13);user-select:none}\n.card .in{position:absolute;inset:2px;border-radius:12px;overflow:hidden;background:linear-gradient(180deg,rgba(8,12,24,.12) 0%,rgba(8,12,24,.25) 45%,rgba(8,12,24,.92) 100%),var(--ph,none) center top/cover no-repeat,#1d2438}\n.card.T{background:linear-gradient(135deg,#9b6bff,#33e0ff)}\n.card.T .in{background:radial-gradient(circle at 50% 38%,#3a2f6b,#161a2c 75%)}\n.card.G{background:linear-gradient(135deg,#ffd23f,#e0a526 50%,#46e08a)}\n.card .v{position:absolute;top:4%;font-family:var(--fd);font-size:1.3em;padding:.08em .32em;border-radius:.45em;line-height:1.05;z-index:1;color:#0b0f1a}\n.card .va{left:5%;background:var(--atk)}.card .vd{right:5%;background:var(--def)}\n.card .v.up{background:var(--deep);color:var(--ok);box-shadow:0 0 0 1.5px var(--ok)}\n.card .v.dn{background:var(--deep);color:var(--bad);box-shadow:0 0 0 1.5px var(--bad)}\n.card.dim-a .va:not(.up):not(.dn),.card.dim-d .vd:not(.up):not(.dn){opacity:.3}\n.card .ps{position:absolute;left:0;right:0;bottom:27%;text-align:center;font-weight:800;font-size:.72em;letter-spacing:.06em;text-shadow:0 1px 2px #000}\n.card .nm{position:absolute;left:4%;right:4%;bottom:15%;font-weight:700;font-size:.86em;text-align:center;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#fff;text-shadow:0 1px 2px #000}\n.card .sub{position:absolute;left:3%;right:3%;bottom:5%;font-size:.52em;font-weight:600;text-align:center;color:var(--mu);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card.T .ico{top:16%;height:24%}\n.card.T .nm{top:43%;bottom:auto}\n.card.T .tef{top:56%}\n.card .tef{position:absolute;left:5%;right:5%;top:58%;font-size:.56em;font-weight:700;text-align:center;line-height:1.15;color:#e9e2ff;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.card .ico{position:absolute;left:22%;right:22%;top:20%;height:30%;display:flex;align-items:center;justify-content:center}\n.card .gk-eff{position:absolute;left:0;right:0;top:5%;text-align:center;font-size:.55em;font-weight:700;color:var(--gold);text-shadow:0 1px 2px #000}\n.card.back{background:#fff;padding:0;border-radius:12px;box-shadow:0 4px 12px #0008}\n.card.back::before{content:\"\";position:absolute;inset:5%;border-radius:7%/5.6%;background:var(--back) center/cover no-repeat}\n.card.back .in{display:none}\n.card.back .in > *{display:none}\n.card.back::after{content:none}\n.hand .card{cursor:pointer}\n.hand .card:hover{transform:translateY(-4px)}\n.hand .card.sel{transform:translateY(-12px);box-shadow:0 0 0 3px var(--lime),0 0 18px #c8f56066}\n.hand.locked .card{cursor:default;opacity:.55}\n.card.flip{animation:flip .45s ease}\n@keyframes flip{0%{transform:rotateY(90deg)}100%{transform:rotateY(0)}}\n.card.lkpop{animation:lk 1.3s ease-out backwards}\n.card.lkpop.flip{animation:flip .45s ease,lk 1.3s ease-out .35s}\n@keyframes lk{0%{box-shadow:0 0 0 0 #46e08acc}35%{box-shadow:0 0 0 5px #46e08a99,0 0 22px 6px #46e08a66}100%{box-shadow:0 0 10px #9b6bff55}}\n.card .pop{position:absolute;left:50%;top:38%;transform:translate(-50%,0);background:var(--ok);color:#0b0f1a;font-weight:800;font-size:.72em;padding:.2em .55em;border-radius:999px;white-space:nowrap;pointer-events:none;opacity:0;animation:pop 1.4s ease-out both;z-index:3;box-shadow:0 2px 0 #0005}\n#fx{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:40;overflow:visible}\n.bolt polyline{fill:none;stroke-linejoin:round;stroke-linecap:round;animation:bdraw .22s ease-out forwards}\n.bolt .glow{stroke:#46e08a;stroke-width:9;opacity:.35;filter:blur(3px)}\n.bolt .core{stroke:#dcffe9;stroke-width:2.4}\n.bolt.strong .glow{stroke-width:13;opacity:.5}.bolt.strong .core{stroke-width:3.4}\n.bolt{animation:bfade 1.25s ease-out forwards}\n@keyframes bdraw{to{stroke-dashoffset:0}}\n@keyframes bfade{0%,55%{opacity:1}30%{opacity:.6}40%{opacity:1}100%{opacity:0}}\n@keyframes pop{0%{opacity:0;transform:translate(-50%,10px) scale(.6)}20%{opacity:1;transform:translate(-50%,0) scale(1.08)}70%{opacity:1;transform:translate(-50%,-14px) scale(1)}100%{opacity:0;transform:translate(-50%,-26px)}}\n\n/* fenêtres */\n/* la fenêtre se limite à la partie visible du cadre (transmise par la partie) */\n.mo{position:fixed;left:0;right:0;top:var(--vt,0px);height:var(--vh,100%);background:#05070dcc;display:flex;align-items:center;justify-content:center;z-index:50;padding:16px}\n.box>.row:last-child{position:sticky;bottom:-18px;background:var(--panel);padding:10px 0 6px;margin-bottom:-4px;z-index:2}\n.mo[hidden]{display:none}\n.box{background:var(--panel);border:2px solid var(--bd);border-radius:20px;padding:18px;max-width:720px;width:100%;max-height:calc(100% - 8px);overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--bd) transparent}\n.box::-webkit-scrollbar{width:8px}.box::-webkit-scrollbar-thumb{background:var(--bd);border-radius:8px}\n.box h2{font-family:var(--fb);font-weight:800;margin:0 0 10px;font-size:20px}\n.box p,.box li{line-height:1.5;font-size:14px;color:var(--mu)}\n.box b{color:var(--tx)}\n.box ol{padding-left:20px}\n.grid{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}\n.grid .card{cursor:pointer}\n.grid .card.sel{box-shadow:0 0 0 3px var(--lime)}\n.row{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;margin-top:10px}\n.coin{width:96px;height:96px;border-radius:50%;margin:10px auto;background:var(--holo);padding:4px}\n.coin > div{width:100%;height:100%;border-radius:50%;background:var(--deep);display:flex;align-items:center;justify-content:center;font-family:var(--fd);font-size:22px;color:var(--gold)}\n.coin.spin{animation:spin 1s ease-out}\n@keyframes spin{0%{transform:rotateY(0)}100%{transform:rotateY(1440deg)}}\n.log{font-size:12px;color:var(--mu2);max-height:110px;overflow:auto;border-top:2px solid var(--bd2);padding-top:4px}\n.log div{padding:1px 0}\n.opts{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0}\n.opts button.on{background:var(--peri);border-color:var(--peri);color:var(--onac)}\n@media (max-width:620px){\n  :root{--cw:clamp(46px,14.5vw,64px)}\n  .side{padding:6px;gap:6px;grid-template-columns:auto 1fr}\n  .side>.col:first-child{grid-row:1;grid-column:1}\n  .side>.col:last-child{grid-row:1;grid-column:2;flex-direction:row;flex-wrap:wrap;justify-content:center;gap:6px}\n  .side>.bench{grid-row:2;grid-column:1/-1;min-height:calc(var(--cw)*1.25 + 24px)}\n  .side .col .zl{font-size:9px}\n  header{border-radius:18px}\n}\n\n/* ---------- boosters ---------- */\n.bn{display:inline-block;min-width:18px;padding:0 5px;border-radius:999px;background:var(--lime);color:#0b0f1a;font-size:11px;margin-left:2px}\n.bn:empty{display:none}\n.bo{position:fixed;inset:0;z-index:45;background:var(--deep);background-image:radial-gradient(circle at 50% 30%,var(--panel) 0,var(--deep) 65%);overflow:auto;\n  padding:max(14px,env(safe-area-inset-top,0px)) max(14px,env(safe-area-inset-right,0px)) 18px max(14px,env(safe-area-inset-left,0px))}\n.bo[hidden]{display:none}\n.bow{max-width:980px;margin:0 auto;display:flex;flex-direction:column;gap:12px;min-height:100%}\n.boh{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:var(--side);border:2px solid var(--peri);border-radius:22px;padding:8px 12px}\n.boh h2{margin:0;font-weight:800;font-size:20px}\n.boh .sp{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap}\n.tabs2{display:flex;gap:6px;flex-wrap:wrap}\n.tabs2 button.on{background:var(--peri);border-color:var(--peri);color:var(--onac)}\n.packs{display:flex;gap:16px;flex-wrap:wrap;justify-content:center;padding:10px 0}\n.pk{--w:clamp(120px,22vw,170px);width:var(--w);aspect-ratio:5/8;border-radius:16px;position:relative;cursor:pointer;flex:none;\n  background:var(--pk1);padding:3px;box-shadow:0 10px 30px #0008,0 0 24px var(--pkg);transition:transform .2s}\n.pk:hover{transform:translateY(-4px) rotate(-1deg)}\n.pk .pf{position:absolute;inset:3px;border-radius:13px;overflow:hidden;background:\n  linear-gradient(115deg,transparent 30%,#ffffff2e 45%,transparent 60%) 0 0/250% 100%,\n  repeating-linear-gradient(135deg,#ffffff08 0 6px,transparent 6px 12px),var(--pk2);animation:sheen 3.5s linear infinite}\n@keyframes sheen{to{background-position:-250% 0,0 0,0 0}}\n.pk .crimp{position:absolute;left:3px;right:3px;height:9%;background:repeating-linear-gradient(90deg,#ffffff30 0 3px,transparent 3px 7px),#0006;z-index:2}\n.pk .crimp.t{top:3px;border-radius:13px 13px 0 0}.pk .crimp.b{bottom:3px;border-radius:0 0 13px 13px}\n.pk .lab{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;text-align:center;z-index:1;padding:12%}\n.pk .lab .em{width:48%;aspect-ratio:1;border-radius:50%;background:var(--holo);display:grid;place-items:center;box-shadow:0 0 18px #fff3}\n.pk .lab .em i{width:80%;aspect-ratio:1;border-radius:50%;background:#0f121d;display:grid;place-items:center;font-style:normal;font-family:var(--fd);color:#fff;font-size:calc(var(--w)*.13)}\n.pk .lab b{font-family:var(--fd);font-weight:400;font-size:calc(var(--w)*.12);line-height:1;text-shadow:0 2px 0 #0006}\n.pk .lab small{font-weight:700;font-size:calc(var(--w)*.075);color:#ffffffcc}\n.pk .cnt{position:absolute;top:-8px;right:-8px;z-index:3;background:var(--lime);color:#0b0f1a;font-family:var(--fd);font-size:15px;min-width:28px;height:28px;border-radius:999px;display:grid;place-items:center;border:2px solid #0f121d}\n.pk.V{--pk1:linear-gradient(135deg,#ffd23f,#ff4fa3);--pk2:linear-gradient(160deg,#ffb020,#c2185b);--pkg:#ffd23f55}\n.pk.N{--pk1:linear-gradient(135deg,#33e0ff,#9b6bff);--pk2:linear-gradient(160deg,#1e88e5,#5e35b1);--pkg:#33e0ff44}\n.pk.D{--pk1:linear-gradient(135deg,#9aa3b8,#35405e);--pk2:linear-gradient(160deg,#4b5878,#232b47);--pkg:#7789b844}\n.pk.empty{opacity:.35;cursor:default}\n/* Boosters illustrés : l'image remplace le fond, le sertissage et l'étiquette générés */\n.pk.img{padding:0;background:#0f121d;border-radius:10px}\n.pk.img .pf{inset:0;border-radius:10px;background:linear-gradient(115deg,transparent 30%,#ffffff26 45%,transparent 60%) 0 0/250% 100%,var(--pkimg) center/100% 100% no-repeat}\n.pk.img .lab,.pk.img .crimp.b{display:none}\n.pk.img .crimp.t{left:0;right:0;top:0;height:4%;border-radius:10px 10px 0 0;background:var(--pkimg) top center/100% auto no-repeat;opacity:0}\n.stage .pk.img.open .crimp.t{opacity:1}\n.stage .pk.img.open .pf{clip-path:inset(4% 0 0 0 round 0 0 10px 10px)}\n.pk.V.img{--pkimg:var(--pkV)}.pk.N.img{--pkimg:var(--pkN)}.pk.D.img{--pkimg:var(--pkD)}\n.packs > div{display:flex;flex-direction:column;align-items:center}\n.odds{font-size:12px;color:var(--mu2);text-align:center;margin-top:10px;line-height:1.5;max-width:180px}\n.odds b{color:var(--tx)}\n/* scène d'ouverture */\n.stage{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;min-height:420px;position:relative}\n.stage .pk{--w:clamp(150px,30vw,210px);cursor:pointer}\n.stage .pk.shake{animation:shake .55s ease-in-out}\n@keyframes shake{0%,100%{transform:rotate(0)}20%{transform:rotate(-5deg) scale(1.03)}40%{transform:rotate(5deg) scale(1.05)}60%{transform:rotate(-4deg) scale(1.05)}80%{transform:rotate(3deg)}}\n.stage .pk.open .crimp.t{animation:tear .6s ease-in forwards}\n@keyframes tear{to{transform:translate(40px,-160px) rotate(28deg);opacity:0}}\n.stage .pk.gone{animation:gone .5s ease-in .45s forwards}\n@keyframes gone{to{transform:translateY(120px) scale(.85);opacity:0}}\n.flash{position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 50%,#fff 0,#fff0 55%);opacity:0}\n.flash.go{animation:fl .7s ease-out}\n@keyframes fl{0%{opacity:0}25%{opacity:.85}100%{opacity:0}}\n.reveal{display:flex;gap:clamp(10px,3vw,26px);justify-content:center;flex-wrap:wrap;position:relative;z-index:1}\n.rc{--rw:clamp(96px,24vw,160px);--cw:var(--rw);position:relative;perspective:900px;opacity:0;animation:deal .5s cubic-bezier(.2,.9,.3,1.2) forwards}\n@keyframes deal{from{opacity:0;transform:translateY(80px) scale(.6) rotate(-8deg)}to{opacity:1;transform:none}}\n.rc .fl{position:relative;width:var(--cw);aspect-ratio:4/5;transform-style:preserve-3d;transition:transform .7s cubic-bezier(.3,1.3,.5,1);cursor:pointer}\n.rc.up .fl{transform:rotateY(180deg);cursor:default}\n.rc .fc{position:absolute;inset:0;backface-visibility:hidden}\n.rc .fc.f{transform:rotateY(180deg)}\n.rc .fc .card{--cw:var(--rw);width:100%}\n.rc .bk{position:relative;width:100%;height:100%;border-radius:14px;background:#fff;box-shadow:0 8px 20px #0008}\n.rc .bk::before{content:\"\";position:absolute;inset:5%;border-radius:7%/5.6%;background:var(--back) center/cover no-repeat}\n.rc .bk div{display:none!important}\n.rc:not(.up) .fl:hover{transform:translateY(-6px)}\n.rc .tag{position:absolute;left:50%;bottom:-30px;transform:translateX(-50%);font-weight:800;font-size:11px;letter-spacing:.08em;padding:3px 10px;border-radius:999px;white-space:nowrap;opacity:0;transition:opacity .3s .5s}\n.rc.up .tag{opacity:1}\n.tag.new{background:var(--lime);color:#0b0f1a}.tag.dup{background:var(--panel);border:2px solid var(--bd);color:var(--mu)}\n.rr{position:absolute;left:50%;top:-28px;transform:translateX(-50%);font-weight:800;font-size:11px;letter-spacing:.1em;text-transform:uppercase;white-space:nowrap;opacity:0;transition:opacity .3s .45s;padding:2px 10px;border-radius:999px;background:#0f121dcc;background-color:transparent}\n.rc.up .rr{opacity:1}\n@property --chA{syntax:'<angle>';inherits:false;initial-value:0deg}\n.rr.c1{color:#c9d1e6}\n.rr.c2,.rr.c3,.rr.c4{background-clip:text;-webkit-background-clip:text;color:transparent;-webkit-text-fill-color:transparent;background-size:250% 100%;animation:rrt 3s linear infinite}\n.rr.c2{background-image:linear-gradient(90deg,#ff4fa3,#ffd23f,#46e08a,#33e0ff,#9b6bff,#ff4fa3)}\n.rr.c3{background-image:linear-gradient(100deg,#f4f7ff,#a8e6ff,#fff3b0,#ffc2e0,#c9b8ff,#f4f7ff);filter:drop-shadow(0 0 3px #fff8)}\n.rr.c4{background-image:linear-gradient(100deg,#fff6c8,#ffd23f,#b8860b,#fff1a8,#d4a017,#fff6c8);filter:drop-shadow(0 0 4px #ffd23f99)}\n@keyframes rrt{to{background-position:-250% 0}}\n.rrw{position:absolute;left:50%;top:-28px;transform:translateX(-50%);padding:2px 10px;border-radius:999px;background:#0f121dcc;opacity:0;transition:opacity .3s .45s;white-space:nowrap}\n.rc.up .rrw{opacity:1}\n.rrw .rr{position:static;transform:none;opacity:1;padding:0;background-color:transparent;transition:none}\n.rc.up.r2 .fc.f{filter:drop-shadow(0 0 14px #9b6bffaa)}\n.rc.up.r3 .fc.f{filter:drop-shadow(0 0 18px #c9b8ffcc) drop-shadow(0 0 4px #fff)}\n.rc.up.r4 .fc.f{filter:drop-shadow(0 0 22px #ffd23fdd);animation:leg 1.6s ease-in-out infinite}\n@keyframes leg{50%{filter:drop-shadow(0 0 34px #ffd23f) drop-shadow(0 0 8px #fff3b0)}}\n/* bordures des raretés (reprises de Galactik Manager) */\n.card.R1{background:linear-gradient(#747881,#5b606b);box-shadow:0 3px 10px #0007}\n.card.R2{background:conic-gradient(from var(--chA),#ff4fa3,#ffd23f,#46e08a,#33e0ff,#9b6bff,#ff4fa3);animation:chs 4s linear infinite;box-shadow:0 0 10px #9b6bff66}\n@keyframes chs{to{--chA:360deg}}\n.card.R3{background:linear-gradient(115deg,#f3e1ff,#a8e6ff,#fff3b0,#ffc2e0,#b8ffd9,#c9b8ff,#f3e1ff) 0 50%/300% 300%;animation:prsh 6s ease-in-out infinite;box-shadow:0 0 14px #c9b8ff99,0 0 3px #fff9}\n@keyframes prsh{50%{background-position:100% 50%}}\n.card.R4{background:linear-gradient(115deg,#fff6c8,#e8b923 18%,#8a6208 34%,#ffe680 50%,#b8860b 66%,#fff1a8 82%,#c99a1c) 0 50%/300% 300%;animation:gld 4s ease-in-out infinite;box-shadow:0 0 14px #ffd23f88,0 0 2px #fff6c8}\n@keyframes gld{50%{background-position:100% 50%}}\n.card.R3 .in::after,.card.R4 .in::after{content:\"\";position:absolute;inset:0;pointer-events:none;background:linear-gradient(105deg,transparent 30%,#ffffff55 47%,#ffffff1a 53%,transparent 70%) 0 0/260% 100%;animation:prsw 3.6s linear infinite;mix-blend-mode:overlay;z-index:2}\n.card.R4 .in::after{background-image:linear-gradient(105deg,transparent 30%,#fff3b077 47%,#ffd23f22 53%,transparent 70%)}\n@keyframes prsw{from{background-position:130% 0}to{background-position:-130% 0}}\n/* animation des cartes rares : halo de la couleur de la rareté + éclairs */\n.halo{position:absolute;left:50%;top:45%;width:min(120vw,1100px);aspect-ratio:1;transform:translate(-50%,-50%) scale(.3);border-radius:50%;pointer-events:none;opacity:0;filter:blur(30px);z-index:0}\n.halo.h2{background:conic-gradient(from 0deg,#ff4fa3,#ffd23f,#46e08a,#33e0ff,#9b6bff,#ff4fa3);-webkit-mask:radial-gradient(circle,#000 0,#0000 62%);mask:radial-gradient(circle,#000 0,#0000 62%)}\n.halo.h3{background:radial-gradient(circle,#ffffff 0,#c9b8ff 22%,#a8e6ff 38%,#ffc2e0 50%,#0000 66%)}\n.halo.h4{background:radial-gradient(circle,#fff6c8 0,#ffd23f 25%,#b8860b 45%,#0000 66%)}\n.halo.go{animation:halo 2.6s ease-out forwards}\n@keyframes halo{0%{opacity:0;transform:translate(-50%,-50%) scale(.3) rotate(0)}20%{opacity:.75;transform:translate(-50%,-50%) scale(1) rotate(40deg)}60%{opacity:.45}100%{opacity:.18;transform:translate(-50%,-50%) scale(1.1) rotate(90deg)}}\n.stage > *:not(.halo):not(.flash){position:relative;z-index:1}\n.shk{animation:shk .4s linear}\n@keyframes shk{20%{transform:translate(4px,-3px)}40%{transform:translate(-4px,3px)}60%{transform:translate(3px,2px)}80%{transform:translate(-2px,-2px)}}\n.coll{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:14px 10px}\n.coll .it{display:flex;flex-direction:column;align-items:center;gap:4px}\n.coll .card{--cw:92px}\n.coll .x{font-size:11px;font-weight:700;color:var(--mu2)}\n.coll .x b{color:var(--lime)}\n.coll .miss .card{opacity:.45}\n.stats{display:flex;gap:8px;flex-wrap:wrap}\n.stats div{background:var(--panel);border:2px solid var(--bd);border-radius:14px;padding:6px 12px;font-size:12px;color:var(--mu2);font-weight:700}\n.stats b{display:block;font-family:var(--fd);font-weight:400;font-size:18px;color:var(--tx)}\n.dks{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px;max-height:42vh;overflow:auto}\n.dks button{border-radius:14px;text-align:left;display:flex;flex-direction:column;gap:2px;padding:8px 12px}\n.dks button small{font-weight:600;font-size:11px;color:var(--mu2);line-height:1.35}\n.dks button.on small{color:var(--onac)}\n.card.gkon{box-shadow:0 0 0 3px var(--gold),0 0 18px #ffd23f88}\n.card.gkon .gk-eff{color:#0b0f1a;background:var(--gold);left:12%;right:12%;border-radius:999px;text-shadow:none}\n.card[data-gk]{cursor:pointer}\n.dkl{display:flex;flex-direction:column;gap:8px}\n.dkc{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:var(--panel);border:2px solid var(--bd);border-radius:16px;padding:10px 14px}\n.dkc.on{border-color:var(--lime)}\n.dkc > div:first-child{flex:1;min-width:180px}.dkc small{display:block;color:var(--mu2);font-weight:600;font-size:12px;margin-top:2px}\n.dkb{display:flex;gap:6px;flex-wrap:wrap}.dkb button{padding:6px 12px;font-size:12px}\n.tagA{background:var(--lime);color:#0b0f1a;font-size:10px;font-weight:800;padding:2px 8px;border-radius:999px;margin-left:4px}\n.dkh{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.dkh input{background:var(--deep);color:var(--tx);border:2px solid var(--bd);border-radius:999px;padding:8px 14px;font:700 14px var(--fb);min-width:0;flex:1;max-width:260px}\n.dks2{font-weight:700;font-size:13px;color:#ffb3c1}.dks2.ok{color:var(--ok)}\n.dkg{display:grid;grid-template-columns:1fr minmax(220px,300px);gap:14px;align-items:start}\n.dkc2{margin-top:8px;max-height:62vh;overflow:auto;padding:4px}\n.dki{display:flex;flex-direction:column;align-items:center;gap:4px;font-size:12px;font-weight:700;color:var(--mu)}\n.dki .card{--cw:88px}\n.dki.sel .card{box-shadow:0 0 0 3px var(--lime)}\n.dki button{padding:2px 10px;font-size:13px}\n.dkls{display:flex;flex-direction:column;gap:4px;max-height:62vh;overflow:auto;background:var(--panel);border:2px solid var(--bd);border-radius:14px;padding:8px}\n.dkls > div{display:grid;grid-template-columns:28px 1fr auto;gap:2px 6px;align-items:center;font-size:13px;font-weight:700}\n.dkls small{grid-column:2;color:var(--mu2);font-weight:600;font-size:11px}\n.dkls button{grid-row:1/3;grid-column:3;padding:2px 10px}\n.dkls span{grid-row:1/3;color:var(--lime);font-family:var(--fd)}\n@media (max-width:700px){.dkg{grid-template-columns:1fr}}\n.boh .lg{width:30px;height:30px;border-radius:50%;background:var(--holo);display:grid;place-items:center;flex:none}\n.boh .lg i{width:24px;height:24px;border-radius:50%;background:var(--deep);display:grid;place-items:center;font-style:normal;font-family:var(--fd);font-size:11px;color:var(--tx)}\n.hub{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:12px;align-items:start}\n.hc{background:var(--panel);border:2px solid var(--bd);border-radius:20px;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0}\n.hc1{grid-row:span 2}\n.hc.glow{border-color:var(--lime);box-shadow:0 0 0 2px var(--lime),0 0 18px #c8f56055}\n.hct b{font-weight:800;font-size:16px;display:block}.hct span{color:var(--mu);font-size:13px;font-weight:600}\n.hcal{background:color-mix(in srgb,var(--peri) 25%,transparent);border:1px solid var(--peri);border-radius:12px;padding:8px 10px;font-weight:700;font-size:13px}\n.hdk{display:flex;flex-direction:column;gap:6px}\n.hdb{border-radius:14px;text-align:left;display:flex;flex-direction:column;gap:2px;padding:8px 12px}\n.hdb small{font-weight:600;font-size:11px;color:var(--mu)}\n.hdb.on{background:var(--peri);border-color:var(--peri);color:var(--onac)}.hdb.on small{color:var(--onac)}\n.hgk{display:flex;gap:10px;align-items:center;background:var(--deep);border-radius:14px;padding:8px}\n.hgk b{display:block;font-size:13px}.hgk small{font-size:12px;color:var(--mu);line-height:1.4;display:block}\n.hpk{display:flex;gap:8px}\n.mini{flex:1;border-radius:12px;padding:10px 6px;text-align:center;color:#fff;display:flex;flex-direction:column;gap:2px;font-size:12px}\n.mini span{font-family:var(--fd);font-size:22px}\n.mini.V{background:linear-gradient(160deg,#ffb020,#c2185b)}.mini.N{background:linear-gradient(160deg,#1e88e5,#5e35b1)}.mini.D{background:linear-gradient(160deg,#4b5878,#232b47)}.mini.off{opacity:.4}\n.hst{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.hst div{background:var(--deep);border-radius:12px;padding:6px;text-align:center}\n.hst b{font-family:var(--fd);font-weight:400;font-size:20px;display:block}.hst small{font-size:10px;color:var(--mu);font-weight:700}\n@media (max-width:620px){.hc1{grid-row:auto}}\n.card.tpl{background:transparent;padding:0;container-type:inline-size;border-radius:4.6cqw;box-shadow:0 4px 14px #0009}\n.card.tpl .in{inset:0;border-radius:4.6cqw;background:linear-gradient(180deg,rgba(8,12,24,0) 45%,rgba(8,12,24,.55) 75%,rgba(8,12,24,.9) 100%),linear-gradient(rgba(8,12,24,.32),rgba(8,12,24,.32)),var(--ph,none) center 20%/cover no-repeat,#1d2438}\n.card.tpl .tsv{position:absolute;inset:0;background:var(--tplgk) center/100% 100% no-repeat;pointer-events:none}\n.card.T.tpl .tsv{background-image:var(--tpltac)}\n.card.J.tpl.pATT .tsv{background-image:var(--tplatt)}\n.card.J.tpl.pATT .tst path{stroke:#ff3131}.card.J.tpl.pATT .tst path.on{fill:#ff3131;filter:drop-shadow(0 0 3px #ff3131)}\n.card.J.tpl.pATT .tpos{color:#ff5a5a}\n.card.J.tpl.pDEF .tsv{background-image:var(--tpldef)}\n.card.J.tpl.pDEF .tst path{stroke:#3b8fe8}.card.J.tpl.pDEF .tst path.on{fill:#3b8fe8;filter:drop-shadow(0 0 3px #3b8fe8)}\n.card.J.tpl.pDEF .tpos{color:#6fb0f0}\n.card.J.tpl.pMID .tsv{background-image:var(--tplmid)}\n.card.J.tpl.pMID .tst path{stroke:#2fb36b}.card.J.tpl.pMID .tst path.on{fill:#2fb36b;filter:drop-shadow(0 0 3px #2fb36b)}\n.card.J.tpl.pMID .tpos{color:#5fd892}\n.card.tpl .tst{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}\n.card.tpl .tst path{fill:none;stroke:#f9c80e;stroke-width:1.6;opacity:.75}\n.card.tpl .tst path.on{fill:#f9c80e;stroke:none;opacity:1;filter:drop-shadow(0 0 3px #f9c80e)}\n.card.tpl .tpos{position:absolute;left:4.4%;width:12.5%;top:4.9%;height:3.4%;display:flex;align-items:center;justify-content:center;font:800 4.4cqw/1 var(--fb);color:#f9c80e;letter-spacing:.04em;text-shadow:0 1px 3px #000}\n.card.tpl .teff{position:absolute;left:24%;right:24%;top:72.8%;min-height:3.6%;display:flex;align-items:center;justify-content:center;text-align:center;background:rgba(15,18,29,.55);border-radius:999px;padding:.6cqw 2.4cqw;font:700 var(--efs,2.8cqw)/1.15 var(--fb);color:#fff;text-transform:uppercase;letter-spacing:.02em;backdrop-filter:blur(2px)}\n.card.tpl .tnm{position:absolute;left:22%;right:34%;top:82.9%;height:5.4%;display:flex;align-items:flex-end;font:400 var(--nfs,6.2cqw)/1 var(--fd);color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 2px 4px #000}\n.card.tpl .tsb{position:absolute;left:29.6%;right:34%;top:88.55%;height:1.8%;display:flex;align-items:center;font:600 2.3cqw/1 var(--fb);color:#e9ecf5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 1px 2px #000}\n.card.tpl.gkon{box-shadow:0 0 0 3px var(--gold),0 0 18px #ffd23f88}\n.card.tpl.gkon .teff{background:#f9c80e;color:#0b0f1a}\n.card.tpl .pop{z-index:4}\n/* Bordures Chromatique / Prismatique sur les cartes à template : anneau posé PAR-DESSUS la carte, sur son contour arrondi */\n.card.tpl.R2,.card.tpl.R3{background:transparent;animation:none}\n.card.tpl.R2::before,.card.tpl.R3::before{content:\"\";position:absolute;inset:0;border-radius:4.6cqw;padding:clamp(1.5px,.85cqw,3.5px);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box exclude,linear-gradient(#000 0 0);pointer-events:none;z-index:5}\n.card.tpl.R2::before{background:conic-gradient(from var(--chA),#ff4fa3,#ffd23f,#46e08a,#33e0ff,#9b6bff,#ff4fa3);animation:chs 4s linear infinite}\n.card.tpl.R3::before{background:linear-gradient(115deg,#f3e1ff,#a8e6ff,#fff3b0,#ffc2e0,#b8ffd9,#c9b8ff,#f3e1ff) 0 50%/300% 300%;animation:prsh 6s ease-in-out infinite}\n.card.tpl.R2{box-shadow:0 0 10px #9b6bff77}\n.card.tpl.R3{box-shadow:0 0 10px #c9b8ff99,0 0 2px #fffa}\n/* Filigrane de rareté (Prismatique) posé sur le template ; bordure et reflet restent actifs */\n.card.tpl .twm{position:absolute;inset:0;background:var(--wm3) center/100% 100% no-repeat;pointer-events:none}\n.card.tpl .twm.w2{background-image:var(--wm2)}\n/* Filigrane « œuvre originale » : personnages canon de la série */\n.card.tpl .two{position:absolute;left:12.6%;top:83.58%;width:14.76%;height:11.91%;background:var(--wmo) center/100% 100% no-repeat;pointer-events:none;opacity:.65}\n\n/* Cartes Légende : anneau doré animé, reflet doré, étincelles et mention LÉGENDE */\n.card.tpl.lg{box-shadow:0 0 14px #ffd23fbb,0 0 34px #ff9d0066}\n.card.tpl.lg::before{content:\"\";position:absolute;inset:0;border-radius:4.6cqw;padding:clamp(2px,1cqw,4px);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask:linear-gradient(#000 0 0) content-box exclude,linear-gradient(#000 0 0);pointer-events:none;z-index:5;background:conic-gradient(from var(--chA),#fff6c8,#ffd23f,#e8a317,#fff1a8,#ffb300,#fff6c8);animation:chs 3s linear infinite}\n.card.tpl.lg .tsv::after{content:\"\";position:absolute;inset:0;border-radius:4.6cqw;background:linear-gradient(115deg,transparent 25%,#fff6c855 38%,#ffd23f44 46%,transparent 58%) 0 0/260% 100%;mix-blend-mode:screen;animation:legsh 2.8s linear infinite;pointer-events:none}\n@keyframes legsh{to{background-position:-260% 0}}\n.card.tpl.lg .tst path,.card.J.tpl.lg[class] .tst path{stroke:#ffd23f}.card.tpl.lg .tst path.on,.card.J.tpl.lg[class] .tst path.on{fill:#ffd23f;stroke:#fff1a8;filter:drop-shadow(0 0 4px #ffb300)}\n.card.tpl .twm.w5{background:none}\n.card.tpl .twm.w5::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 20% 30%,#fff 0 .5cqw,transparent .9cqw),radial-gradient(circle at 78% 18%,#fff6c8 0 .6cqw,transparent 1cqw),radial-gradient(circle at 64% 58%,#fff 0 .4cqw,transparent .8cqw),radial-gradient(circle at 30% 70%,#ffd23f 0 .5cqw,transparent .9cqw),radial-gradient(circle at 86% 46%,#fff 0 .45cqw,transparent .85cqw);animation:twk 2.2s ease-in-out infinite alternate;pointer-events:none}\n@keyframes twk{0%{opacity:.15}100%{opacity:1}}\n.card.tpl .twm.w5::after{content:\"LÉGENDE\";position:absolute;right:15%;top:69%;font:400 4.4cqw/1 var(--fd);letter-spacing:.06em;color:#ffd23f;text-shadow:0 0 6px #ff9d00,0 1px 2px #000;transform:rotate(-8deg)}\n.atoast{position:fixed;left:50%;bottom:18px;transform:translate(-50%,40px);opacity:0;z-index:80;background:#141a2e;border:2px solid #ffd23f;border-radius:14px;padding:10px 16px;display:flex;flex-direction:column;gap:2px;box-shadow:0 10px 30px #000a,0 0 20px #ffd23f44;transition:.4s;max-width:90vw;text-align:center}\n.atoast.go{transform:translate(-50%,0);opacity:1}.atoast b{font-size:15px;color:#ffd23f}.atoast small{font-size:12px;color:#fff}\n.atoast.leg{box-shadow:0 10px 30px #000a,0 0 34px #ffd23f88}\n\n/* Règles racontées par Clamp */\n.clh{display:flex;align-items:center;gap:10px;margin-bottom:8px}\n.cla{position:relative;width:58px;height:58px;flex:none;border-radius:50%;overflow:hidden;border:2px solid var(--peri,#6cc9ff)}\n.cla svg,.cla img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.cla img{object-position:50% 30%}\n.cln{display:flex;flex-direction:column}.cln b{font-size:16px}.cln small{font-size:12px;color:var(--mu)}\n.clt{font-size:15px!important;line-height:1.55!important;color:var(--tx)!important;min-height:4.6em}\n.cld{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 6px}.cld i{width:9px;height:9px;border-radius:50%;background:#ffffff26;cursor:pointer}.cld i.pa{background:#ffffff66}.cld i.on{background:var(--peri,#6cc9ff);box-shadow:0 0 8px var(--peri,#6cc9ff)}\n/* Halo de sélection : un anneau posé PAR-DESSUS la carte, qui en suit exactement le contour (et non une lueur derrière) */\n.card.sel::after,.dki.sel .card::after,.card.gkon::after{content:\"\";position:absolute;inset:-4px;border-radius:calc(14px + 4px);border:3px solid var(--lime);box-shadow:0 0 14px #c8f560aa,inset 0 0 12px #c8f56066;pointer-events:none;z-index:6}\n.card.tpl.sel::after,.dki.sel .card.tpl::after,.card.tpl.gkon::after{border-radius:calc(4.6cqw + 4px)}\n.card.gkon::after{border-color:var(--gold);box-shadow:0 0 14px #ffd23faa,inset 0 0 12px #ffd23f66}\n.hand .card.sel,.grid .card.sel,.dki.sel .card,.card.gkon,.card.tpl.gkon{box-shadow:0 6px 18px #000a}\n.card.sel.back::after{content:\"\"}\n/* cartes Tactique sur template */\n.card.T.tpl .in{background:radial-gradient(circle at 50% 42%,#3a2470 0,#1a1238 55%,#0e0b1f 100%)}\n.card.T.tpl .tico{position:absolute;left:30%;right:22%;top:30%;height:30%;opacity:.55;display:flex;align-items:center;justify-content:center}\n.card.T.tpl .tst path{stroke:#8f5cff}.card.T.tpl .tst path.on{fill:#8f5cff;filter:drop-shadow(0 0 3px #8f5cff)}\n.card.T.tpl .tpos{color:#a98bff}\n.card.tpl .orb{position:absolute;left:83.2%;width:12.55%;aspect-ratio:1;border-radius:50%;display:flex;align-items:center;justify-content:center;font:400 5.6cqw/1 var(--fd);color:#fff;text-shadow:0 1px 3px #000,0 0 6px #000a}\n.card.tpl .orb.od{top:23.03%}\n.card.tpl .orb.oa{top:34.62%}\n.card.tpl .orb.up{color:var(--ok)}\n.card.tpl .orb.dn{color:#ff5c6c}\n.card.tpl.dim-a .orb.oa:not(.up):not(.dn),.card.tpl.dim-d .orb.od:not(.up):not(.dn){opacity:.35}\n.card.tpl .tlogo{position:absolute;left:25%;top:9.6%;width:13%;aspect-ratio:1;object-fit:contain;filter:drop-shadow(0 2px 4px #000c)}\n#zoomp{position:fixed;z-index:70;pointer-events:none;opacity:0;transform:scale(.92);transition:opacity .12s,transform .12s;filter:drop-shadow(0 18px 30px #000c)}\n#zoomp.on{opacity:1;transform:none}\n#zoomp .card{--cw:min(540px,92vw,calc((100vh - 20px) * .8));transform:none!important;animation:none!important;opacity:1!important;cursor:default}\n#zoomp .pop{display:none}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n</style></head><body>\n\n<div class=\"app\">\n  <header>\n    <div class=\"hbtn\"><button class=\"ghost\" id=\"tDuel\">Accueil</button><button class=\"ghost\" id=\"bBo\">Boosters <span id=\"boN\" class=\"bn\"></span></button><button class=\"ghost\" id=\"tColl\">Collection</button><button class=\"ghost\" id=\"tDecks\">Mes decks</button><button class=\"ghost\" id=\"bRules\">Règles</button></div>\n    <div class=\"score\"><span id=\"nmMe\">Vous</span><b id=\"scMe\">0</b><span>–</span><b id=\"scAi\">0</b><span>IA</span></div>\n  </header>\n\n  <section class=\"side\" id=\"sideAi\"></section>\n  <div class=\"opp-hand\" id=\"oppHand\"></div>\n  <div class=\"mid\"><div class=\"msg\" id=\"msg\"></div><button id=\"bAct\" hidden>Valider</button></div>\n  <section class=\"side me\" id=\"sideMe\"></section>\n  <div class=\"handbar\"><div class=\"hand\" id=\"hand\"></div></div>\n  <div class=\"log\" id=\"log\"></div>\n</div>\n\n<svg id=\"fx\" aria-hidden=\"true\"></svg>\n<div class=\"bo\" id=\"bo\" hidden><div class=\"bow\" id=\"bow\"></div></div>\n<div class=\"mo\" id=\"mo\" hidden><div class=\"box\" id=\"box\"></div></div>\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));\nconst shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };\nconst wait = ms => { const g = G; return new Promise(r => setTimeout(() => { if (G === g) r(); }, ms * SPEED)); };\nlet SPEED = 1;\n\n/* ---------- cartes : équipes, planètes et joueurs de Galactik Manager ---------- */\n// Données de la carrière (pont avec Galactik Manager)\nconst H = parent.TCGH, ST = H.st();\nconst ROSTER = ST.roster;\n// Cartes Légende d'événement : personnages de la série débloqués par des exploits de la carrière (jamais en booster).\nconst EVR = (H.evRows && H.evRows()) || [];\nconst rowOf = n => ROSTER.find(r => r[0] == n) || EVR.find(r => r[0] == n);\nconst TEAMS = ['Snow Kids', 'Shadows', 'Team Paradisia', 'Lightnings', 'Wambas', 'Rykers', 'Xenons', 'Tigres Rouges', 'Pirates', 'Elektras', 'Cyclopes', 'Vortex', 'Technodroids', 'Comet']\n  .filter(tm => ROSTER.some(r => r[2] == tm)).map(tm => [tm, (ROSTER.find(r => r[2] == tm && r[6] == tm) || ROSTER.find(r => r[2] == tm))[3]]);\n// Cartes Tactique : mêmes valeurs et même effet pour toutes les cartes du même nom. L'effet s'applique quand la carte est jouée.\nconst TACT = {\n  'Pressing haut':       { a: 12, d: 8,  k: 'oppbest', x: 8,   s: 'Meilleure carte adverse −8', t: 'La meilleure carte du banc adverse perd 8.' },\n  'Contre-éclair':       { a: 8,  d: 16, k: 'nextatk', x: 20,  s: 'Si blocage : +20 à votre prochaine attaque', t: 'Si vous bloquez l’attaque, votre prochaine attaque gagne +20.' },\n  'Une-deux':            { a: 12, d: 10, k: 'pairs', x: 8,     s: '+8 avec 2 joueurs', t: '+8 au total si votre banc contient au moins 2 cartes Joueur.' },\n  'Mur compact':         { a: 6,  d: 16, k: 'def', x: 8,       s: '+8 en défense', t: '+8 au total quand vous défendez.' },\n  'Appel en profondeur': { a: 16, d: 6,  k: 'atk', x: 10,      s: '+10 en attaque', t: '+10 au total quand vous attaquez.' },\n  'Bloc bas':            { a: 6,  d: 15, k: 'recov1', x: 0,    s: 'Si blocage : 1 carte récupérée en plus', t: 'Si vous bloquez, vous récupérez une carte de plus dans votre défausse.' },\n  'Jeu sans ballon':     { a: 12, d: 12, k: 'draw', x: 0,      s: 'Prochain tour : main de 6', t: 'Au prochain tour, vous complétez votre main à 6 cartes.' },\n  'Relance rapide':      { a: 8,  d: 12, k: 'recovhand', x: 0, s: 'Si blocage : +1 carte récupérée, en main', t: 'Si vous bloquez, vous récupérez une carte de plus, et les cartes récupérées vont dans votre main.' },\n  'Tacle glissé':        { a: 6,  d: 12, k: 'pdisc', x: 0,     s: 'L’adversaire défausse sa meilleure carte au prochain tour', t: 'Au prochain tour, après la pioche, l’adversaire défausse sa meilleure carte.' },\n  'Concentration':       { a: 10, d: 10, k: 'antimalus', x: 6, s: '+6, ignore les malus', t: '+6 au total, et vos cartes ignorent les malus adverses pendant ce duel.' },\n  'Esprit d’équipe':     { a: 8,  d: 8,  k: 'synp', x: 6,      s: '+6 par joueur en synergie', t: '+6 au total pour chaque carte Joueur de votre banc qui reçoit un bonus de synergie.' },\n  'Souffle du Fluide':   { a: 10, d: 10, k: 'tot', x: 8,       s: '+8 au total', t: '+8 au total, en attaque comme en défense.' },\n  'Hors-jeu':            { a: 4,  d: 12, k: 'oppA', x: 10,     s: 'En défense : attaque adverse −10', t: 'Quand vous défendez, l’attaque adverse perd 10.' },\n  'Frappe lointaine':    { a: 20, d: 4,  k: 'atk', x: 6,       s: '+6 en attaque', t: '+6 au total quand vous attaquez.' },\n  'Temps mort':          { a: 8,  d: 8,  k: 'recovnow', x: 0,  s: 'Après le duel : un joueur de la défausse en main', t: 'Après le duel, vous reprenez en main une carte Joueur de votre défausse.' },\n  'Marquage individuel': { a: 5,  d: 10, k: 'nosyn', x: 0,     s: 'Annule les synergies adverses', t: 'Les bonus de synergie du banc adverse sont annulés pendant ce duel.' },\n};\nconst TN = Object.keys(TACT);\n// Tactiques des decks de départ (15 cartes, les mêmes pour toutes les équipes)\nconst TSTART = ['Pressing haut', 'Pressing haut', 'Mur compact', 'Mur compact', 'Appel en profondeur', 'Appel en profondeur', 'Une-deux', 'Une-deux', 'Bloc bas', 'Bloc bas', 'Jeu sans ballon', 'Jeu sans ballon', 'Souffle du Fluide', 'Souffle du Fluide', 'Concentration'];\nconst TCOL = ['#3ad1ff','#8a7dff','#ff6fb5','#ffd23f','#4cf2a0','#ff9f43','#36e0d0','#ff5c5c','#c9a46a','#b48cff','#7fd35c','#5c9dff','#9aa7b8','#ffb3e1'];\nconst tcol = tm => TCOL[TEAMS.findIndex(t => t[0] == tm) % TCOL.length] || '#9aa0d0';\nconst POS = { ATT: 'Attaquant', MID: 'Milieu', DEF: 'Défenseur', GK: 'Gardien' };\nlet UID = 0;\nfunction hrng(str) { let h = 2166136261; for (const ch of str) { h ^= ch.codePointAt(0); h = Math.imul(h, 16777619); } return () => { h = Math.imul(h ^ (h >>> 15), 2246822507); h = Math.imul(h ^ (h >>> 13), 3266489909); h ^= h >>> 16; return (h >>> 0) / 4294967296; }; }\nfunction statsOf(n, pos, o = 68) { // valeurs fixes par joueur : total selon la note générale, réparti selon le poste\n  const r = hrng(n), tot = Math.round(70 + (o - 68) * 0.9) + Math.floor(r() * 7) - 3;\n  const sh = pos == 'ATT' ? .70 + r() * .08 : pos == 'DEF' ? .22 + r() * .08 : .45 + r() * .10;\n  const a = Math.round(tot * sh); return [a, tot - a];\n}\nfunction mkCard(row) {\n  const [n, pos, tm, pl, o, fl] = row;\n  if (pos == 'GK') { const gks = ROSTER.filter(r => r[1] == 'GK' && r[2] == tm).sort((x, y) => x[4] - y[4]); return { id: ++UID, t: 'G', n, pos, tm, pl, o, fl, slot: gks[0][0] == n ? 0 : 1 }; }\n  const [a, d] = statsOf(n, pos, o);\n  return { id: ++UID, t: 'J', n, pos, tm, pl, o, fl, a, d };\n}\nfunction mkTac(n) { n = n || TN[rnd(0, TN.length - 1)]; const T = TACT[n]; return { id: ++UID, t: 'T', n, a: T.a, d: T.d, k: T.k, x: T.x }; }\n// Deck de départ : 10 joueurs de champ en 2 exemplaires + 1 de plus pour les 5 meilleurs + 15 tactiques ; gardien le moins bien noté.\nfunction starterRows(tm) {\n  const f = ROSTER.filter(r => r[2] == tm && r[1] != 'GK'), top = f.slice().sort((x, y) => y[4] - x[4]).slice(0, 5);\n  return [...f, ...f, ...top];\n}\nfunction mkStarter(tm, slot) {\n  const deck = starterRows(tm).map(mkCard);\n  TSTART.forEach(n => deck.push(mkTac(n)));\n  const gks = ROSTER.filter(r => r[1] == 'GK' && r[2] == tm).sort((x, y) => x[4] - y[4]);\n  return { deck: shuffle(deck), gk: mkCard(gks[slot || 0]), tms: [tm] };\n}\n// Renfort des decks de départ : plus le deck est faible, plus l'effet du remplaçant ajoute de points (calculé à partir du deck réel).\nconst STR = Object.fromEntries(TEAMS.map(([tm]) => { const v = starterRows(tm).map(r => statsOf(r[0], r[1], r[4])); return [tm, v.reduce((s, x) => s + x[0] + x[1], 0) / v.length]; }));\nconst STRMAX = Math.max(...Object.values(STR));\nconst renfort = tm => Math.max(0, Math.round(1.2 * (STRMAX - STR[tm])));\n\n/* ---------- effets des gardiens ---------- */\n// c : 'E' (joueurs de l'équipe du gardien) ou 'P' (joueurs de la planète de son équipe) ; n : nombre requis sur le banc.\nconst GKE = {\n  'Snow Kids':     [{ c: 'E', n: 2, k: 'tot', x: 3 },        { c: 'E', n: 3, k: 'per', x: 8 }],\n  'Shadows':       [{ c: 'E', n: 2, k: 'oppbest', x: 5 },    { c: 'E', n: 3, k: 'pdisc' }],\n  'Team Paradisia':[{ c: 'E', n: 2, k: 'def', x: 8 },        { c: 'P', n: 2, k: 'tacp', x: 8 }],\n  'Lightnings':    [{ c: 'E', n: 2, k: 'atk', x: 4 },        { c: 'E', n: 2, k: 'atk', x: 14 }],\n  'Wambas':        [{ c: 'E', n: 2, k: 'perdef', x: 5 },     { c: 'E', n: 3, k: 'best' }],\n  'Rykers':        [{ c: 'E', n: 2, k: 'comeback', x: 4 },   { c: 'E', n: 2, k: 'recov2', x: 3 }],\n  'Xenons':        [{ c: 'E', n: 2, k: 'draw' },             { c: 'E', n: 2, k: 'xen' }],\n  'Tigres Rouges': [{ c: 'P', n: 2, k: 'atk', x: 10 },       { c: 'E', n: 2, k: 'oppdefA', x: 12 }],\n  'Pirates':       [{ c: 'E', n: 2, k: 'pdisc_goal' },       { c: 'E', n: 3, k: 'nosyn' }],\n  'Elektras':      [{ c: 'E', n: 2, k: 'opp', x: 6 },        { c: 'P', n: 2, k: 'oppbest', x: 10 }],\n  'Cyclopes':      [{ c: 'E', n: 2, k: 'tiewin', x: 3 },     { c: 'E', n: 2, k: 'blockdraw', x: 9 }],\n  'Vortex':        [{ c: 'P', n: 2, k: 'antimalus', x: 5 },  { c: 'E', n: 3, k: 'oppworst' }],\n  'Technodroids':  [{ c: 'E', n: 2, k: 'floor', x: 30 },     { c: 'E', n: 3, k: 'tot', x: 22 }],\n  'Comet':         [{ c: 'E', n: 2, k: 'goaldisc', x: 3 },   { c: 'E', n: 2, k: 'recovhand', x: 4 }],\n};\nconst PLAN = Object.fromEntries(TEAMS);\nfunction gkEff(gk) { const e = (GKE[gk.tm] || [])[gk.slot || 0]; if (!e) return null; return { ...e, b: gk.slot ? 0 : renfort(gk.tm) }; }\nfunction effText(gk, short) {\n  const e = gkEff(gk); if (!e) return '';\n  const cond = `${e.c == 'E' ? gk.tm : 'Planète ' + PLAN[gk.tm]} ×${e.n - (gk.r == 5 ? 1 : 0)}`;\n  const T = {\n    tot: `+${e.x} au total`, per: `+${e.x} par joueur ${gk.tm} sur le banc`, atk: `+${e.x} en attaque`, def: `+${e.x} en défense`,\n    perdef: `+${e.x} par Défenseur sur le banc`, comeback: `+${e.x}, et +${e.x} de plus par but encaissé`,\n    oppbest: `la meilleure carte adverse perd ${e.x}`, oppworst: `la meilleure carte adverse perd un tiers de sa valeur`,\n    opp: `−${e.x} au total adverse`, oppdefA: `quand vous attaquez, la défense adverse perd ${e.x}`,\n    tacp: `chaque Tactique du banc gagne +${e.x}`, floor: `chaque joueur vaut au moins ${e.x}`, best: `votre joueur le plus faible utilise sa meilleure valeur`,\n    nosyn: `les synergies adverses sont annulées`, tiewin: `+${e.x}, et vous gagnez les égalités`, antimalus: `+${e.x}, et vos cartes ignorent les malus`,\n    draw: `au prochain tour, votre main passe à 6 cartes`, xen: `au prochain tour, main de 6 pour vous et de 4 pour l’adversaire`,\n    pdisc: `au prochain tour, l’adversaire défausse sa meilleure carte après la pioche`,\n    pdisc_goal: `si vous marquez, l’adversaire défausse sa meilleure carte au prochain tour, après la pioche`,\n    recov2: `+${e.x} en défense ; si vous bloquez, vous récupérez 2 cartes`, blockdraw: `+${e.x} en défense ; si vous bloquez, main de 6 au prochain tour`,\n    goaldisc: `+${e.x} ; si vous encaissez un but, la carte de but vient de votre défausse`, recovhand: `+${e.x} ; si vous bloquez, la carte récupérée va dans votre main`,\n  }[e.k];\n  return short ? `${cond} : ${T}${e.b ? ` · renfort +${e.b}` : ''}` : `<b>${cond}</b> — ${T}${e.b ? `, et +${e.b} au total (renfort du deck de départ)` : ''}.`;\n}\nfunction effOn(P, bench) {\n  const e = gkEff(P.gk); if (!e) return null;\n  const n = bench.filter(c => c.t == 'J' && (e.c == 'E' ? c.tm == P.gk.tm : c.pl == PLAN[P.gk.tm])).length;\n  return n >= e.n - (P.gk.r == 5 ? 1 : 0) ? e : null;\n}\n// Calcul complet d'un banc : valeurs des cartes (synergies, effets), bonus du gardien, malus adverses.\nfunction sideEval(P, bench, role, O, Ob) {\n  const k = role == 'A' ? 'a' : 'd', e = effOn(P, bench), oe = O ? effOn(O, Ob || []) : null;\n  const d = new Map(); let flat = 0, mal = 0, syn = 0, effc = 0, malc = 0, tac = 0;\n  const TK = (b, kk) => (b || []).filter(c => c.t == 'T' && c.k == kk);\n  const nosyn = (oe && oe.k == 'nosyn') || TK(Ob, 'nosyn').length > 0, immune = (e && e.k == 'antimalus') || TK(bench, 'antimalus').length > 0;\n  const add = (c, v, kind) => { d.set(c.id, (d.get(c.id) || 0) + v); if (kind == 'e') effc += v; if (kind == 'm') malc -= v; };\n  bench.forEach(c => {\n    if (c.t == 'J' && !nosyn) { const b = bonusOf(c, bench, P.gk); if (b) { add(c, b); syn += b; } }\n    if (e && e.k == 'tacp' && c.t == 'T') add(c, e.x, 'e');\n    if (e && e.k == 'floor' && c.t == 'J' && c[k] < e.x) add(c, e.x - c[k], 'e');\n  });\n  if (e && e.k == 'best') { const js = bench.filter(c => c.t == 'J'); if (js.length) { const w = js.reduce((m, c) => c[k] + (d.get(c.id) || 0) < m[k] + (d.get(m.id) || 0) ? c : m); add(w, Math.max(w.a, w.d) - w[k], 'e'); } }\n  if (e) {\n    if (['tot', 'tiewin', 'antimalus', 'goaldisc', 'recovhand'].includes(e.k)) flat += e.x;\n    if (e.k == 'per') flat += e.x * bench.filter(c => c.t == 'J' && c.tm == P.gk.tm).length;\n    if (e.k == 'atk' && role == 'A') flat += e.x;\n    if (e.k == 'def' && role == 'D') flat += e.x;\n    if (['recov2', 'blockdraw'].includes(e.k) && role == 'D') flat += e.x;\n    if (e.k == 'perdef') flat += e.x * bench.filter(c => c.pos == 'DEF').length;\n    if (e.k == 'comeback') flat += e.x * (1 + P.goals.length);\n    flat += e.b || 0;\n  }\n  // effets des tactiques jouées sur ce banc\n  bench.forEach(c => {\n    if (c.t != 'T' || !c.k) return;\n    if (c.k == 'tot' || c.k == 'antimalus') tac += c.x;\n    if (c.k == 'atk' && role == 'A') tac += c.x;\n    if (c.k == 'def' && role == 'D') tac += c.x;\n    if (c.k == 'pairs' && bench.filter(q => q.t == 'J').length >= 2) tac += c.x;\n    if (c.k == 'synp') tac += c.x * bench.filter(q => q.t == 'J' && bonusOf(q, bench, P.gk) > 0 && !nosyn).length;\n  });\n  if (role == 'A' && P.nb) tac += P.nb;\n  flat += tac;\n  if (O && !immune) {\n    const val = c => c[k] + (d.get(c.id) || 0);\n    const best = bench.length ? bench.reduce((m, c) => val(c) > val(m) ? c : m) : null;\n    TK(Ob, 'oppbest').forEach(c => { if (best) add(best, -Math.min(c.x, val(best)), 'm'); });\n    TK(Ob, 'oppA').forEach(c => { if (role == 'A') mal += c.x; });\n  }\n  if (oe && !immune) {\n    const val = c => c[k] + (d.get(c.id) || 0);\n    const best = bench.length ? bench.reduce((m, c) => val(c) > val(m) ? c : m) : null;\n    if (oe.k == 'oppbest' && best) { const v = Math.min(oe.x, val(best)); add(best, -v, 'm'); }\n    if (oe.k == 'oppworst' && best) { add(best, -Math.floor(val(best) / 3), 'm'); }\n    if (oe.k == 'opp') mal += oe.x;\n    if (oe.k == 'oppdefA' && role == 'D') mal += oe.x;\n  }\n  const cards = bench.reduce((s, c) => s + c[k] + (d.get(c.id) || 0), 0);\n  return { tot: cards + flat - mal, d, e, flat, mal, syn, tac, eff: flat - tac + effc, malT: mal + malc };\n}\n\n/* ---------- synergies ---------- */\n// même planète OU même équipe : +5 ; même planète ET même équipe : +10 ; on garde le meilleur lien, sans cumul.\nfunction linkV(x, y) { const p = x.pl == y.pl, t = x.tm == y.tm; return p && t ? 10 : p || t ? 5 : 0; }\nfunction bonusOf(c, bench, gk) {\n  if (c.t != 'J') return 0;\n  let b = 0;\n  for (const o of bench) if (o !== c && o.t == 'J') b = Math.max(b, linkV(c, o));\n  if (gk) b = Math.max(b, linkV(c, gk));\n  return b + (c.mk || 0); // c.mk : futurs bonus/malus d'effets\n}\nfunction whyOf(c, bench, gk) { // meilleur lien d'une carte : bonus, type et carte d'origine\n  let best = { b: 0 };\n  const test = (o, isGk) => { const v = linkV(c, o); if (v > best.b) best = { b: v, k: v == 10 ? 'équipe + planète' : c.tm == o.tm ? 'équipe' : 'planète', w: isGk ? 'le gardien' : o.n }; };\n  if (c.t == 'J') { for (const o of bench) if (o !== c && o.t == 'J') test(o, false); if (gk) test(gk, true); }\n  return best;\n}\nconst tot = (bench, gk, k) => bench.reduce((s, c) => s + c[k] + bonusOf(c, bench, gk), 0); // (mort subite)\n\nfunction bolt({ a, b, v }) { // éclair vert entre deux cartes, qui crépite puis s'efface\n  const ea = document.querySelector(`.card[data-id=\"${a}\"]:not(.back)`), eb = document.querySelector(`.card[data-id=\"${b}\"]:not(.back)`);\n  const fx = $('fx'); if (!ea || !eb || !fx) return;\n  const ra = ea.getBoundingClientRect(), rb = eb.getBoundingClientRect();\n  const x1 = ra.left + ra.width / 2, y1 = ra.top + ra.height / 2, x2 = rb.left + rb.width / 2, y2 = rb.top + rb.height / 2;\n  const L = Math.hypot(x2 - x1, y2 - y1), nx = -(y2 - y1) / L, ny = (x2 - x1) / L, amp = Math.min(14, L / 9);\n  const pts = () => { const n = Math.max(5, Math.round(L / 22)), out = [[x1, y1]]; for (let i = 1; i < n; i++) { const t = i / n, o = (Math.random() * 2 - 1) * amp; out.push([x1 + (x2 - x1) * t + nx * o, y1 + (y2 - y1) * t + ny * o]); } out.push([x2, y2]); return out.map(p => p.map(Math.round).join(',')).join(' '); };\n  const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');\n  g.setAttribute('class', 'bolt' + (v == 10 ? ' strong' : ''));\n  g.innerHTML = `<polyline class=\"glow\" points=\"${pts()}\"/><polyline class=\"core\" points=\"${pts()}\"/>`;\n  g.querySelectorAll('polyline').forEach(pl => { pl.style.strokeDasharray = L * 1.4; pl.style.strokeDashoffset = L * 1.4; });\n  fx.appendChild(g);\n  let n = 0; const it = setInterval(() => { if (++n > 8) { clearInterval(it); return; } g.querySelectorAll('polyline').forEach(pl => pl.setAttribute('points', pts())); }, 80);\n  setTimeout(() => g.remove(), 1300);\n}\nfunction isNew(key) { G.cur.add(key); return !G.prev.has(key); }\nconst TPLPOS = ['ATT', 'DEF', 'MID']; // postes qui ont déjà leur template\nconst GKSTARS = [\"M 98.83 109.68 L 106.92 124.46 L 121.71 132.55 L 106.92 140.64 L 98.83 155.42 L 90.75 140.64 L 75.96 132.55 L 90.75 124.46 Z M 98.83 109.68 \", \"M 98.83 162.84 L 106.92 177.63 L 121.71 185.71 L 106.92 193.80 L 98.83 208.58 L 90.75 193.80 L 75.96 185.71 L 90.75 177.63 Z M 98.83 162.84 \", \"M 98.83 216.01 L 106.92 230.79 L 121.71 238.87 L 106.92 246.96 L 98.83 261.75 L 90.75 246.96 L 75.96 238.87 L 90.75 230.79 Z M 98.83 216.01 \", \"M 98.83 269.17 L 106.92 283.96 L 121.71 292.04 L 106.92 300.13 L 98.83 314.91 L 90.75 300.13 L 75.96 292.04 L 90.75 283.96 Z M 98.83 269.17 \"];\nconst PCOL = { ATT: 'var(--pATT)', MID: 'var(--pMID)', DEF: 'var(--pDEF)', GK: 'var(--pGK)' };\nconst PHC = {}, LGC = {};\nconst logoOf = tm => { if (!(tm in LGC)) LGC[tm] = (H.logo && H.logo(tm)) || ''; return LGC[tm]; };\nconst phOf = c => { if (c.t == 'T') return ''; if (!(c.n in PHC)) PHC[c.n] = H.ph(c.n) || ''; return PHC[c.n] ? `--ph:url('${PHC[c.n]}')` : ''; };\nconst TICO = '<svg viewBox=\"0 0 40 34\" width=\"100%\" height=\"100%\" aria-hidden=\"true\"><rect x=\"3\" y=\"3\" width=\"34\" height=\"28\" rx=\"3\" fill=\"none\" stroke=\"#b9a3ff\" stroke-width=\"1.6\"/><path d=\"M20 3v28\" stroke=\"#b9a3ff\" stroke-width=\"1.2\"/><circle cx=\"20\" cy=\"17\" r=\"5\" fill=\"none\" stroke=\"#b9a3ff\" stroke-width=\"1.2\"/><path d=\"M8 24l6-6m0 0h-4m4 0v4M30 10l-6 6\" stroke=\"#ff4fa3\" stroke-width=\"2.2\" fill=\"none\" stroke-linecap=\"round\"/></svg>';\n// o.da / o.dd : modification de l'attaque / de la défense (bonus en vert, malus en rouge)\nfunction vb(base, delta, cls) {\n  const m = delta > 0 ? ' up' : delta < 0 ? ' dn' : '';\n  return `<span class=\"v ${cls}${m}\">${base + (delta || 0)}</span>`;\n}\n// Pas d'infobulle du navigateur sur les cartes : l'aperçu agrandi suffit.\nfunction cardHTML(c, o) { return cardHTML0(c, o || {}).replace(/^(<div[^>]*?) title=\"[^\"]*\"/, '$1'); }\nfunction cardHTML0(c, o = {}) {\n  if (!c) return '';\n  const cls = ['card', c.t, o.back ? 'back' : '', o.sel ? 'sel' : '', o.flip ? 'flip' : '', o.pop && !o.back ? 'lkpop' : '', o.role == 'A' ? 'dim-d' : o.role == 'D' ? 'dim-a' : '', c.r == 5 && !o.back ? 'lg' : ''].join(' ');\n  const pop = o.pop && !o.back ? `<span class=\"pop\" style=\"animation-delay:${o.dl || 0}ms\">${o.pop}</span>` : '';\n  const sub = c.t == 'T' ? `<div class=\"sub\">Tactique</div><div class=\"tef\">${(TACT[c.n] || {}).s || ''}</div>` : `<div class=\"sub\">${c.tm} · ${c.pl}</div>`;\n  if (c.t == 'G') {\n    const r = c.r || 1, et = effText(c, true).replace(/ · renfort \\+\\d+/, ''), L = et.length;\n    const efs = L > 95 ? 1.75 : L > 75 ? 2 : L > 55 ? 2.3 : L > 38 ? 2.55 : 2.8, nfs = c.n.length > 14 ? 4.3 : c.n.length > 11 ? 5 : c.n.length > 8 ? 5.7 : 6.2;\n    const st = GKSTARS.map((d, i) => `<path class=\"${i < r ? 'on' : ''}\" d=\"${d}\"/>`).join('');\n    return `<div class=\"${cls} tpl${o.on ? ' gkon' : ''}\" data-id=\"${c.id}\" data-gk=\"1\" style=\"${phOf(c)}\" title=\"${c.n} — gardien ${c.slot ? 'titulaire' : 'remplaçant'}, ${c.tm} (${c.pl}). ${RAR ? RAR[r] + '. ' : ''}Effet : ${effText(c, true)}\"><div class=\"in\">${c.fl == 'c' ? '<div class=\"two\"></div>' : ''}<div class=\"tsv\"></div>${r == 2 || r == 3 || r == 5 ? `<div class=\"twm w${r}\"></div>` : ''}<svg class=\"tst\" viewBox=\"0 0 573.75 717.75\" preserveAspectRatio=\"none\" aria-hidden=\"true\">${st}</svg><div class=\"tpos\">GK</div>${logoOf(c.tm) ? `<img class=\"tlogo\" alt=\"\" src=\"${logoOf(c.tm)}\">` : ''}<div class=\"teff\" style=\"--efs:${efs}cqw\">${et}</div><div class=\"tnm\" style=\"--nfs:${nfs}cqw\">${c.n}</div><div class=\"tsb\">${c.pl} - ${c.tm}</div></div>${pop}</div>`;\n  }\n  if (c.t == 'J' && TPLPOS.includes(c.pos)) {\n    const r = c.r || 1, nfs = c.n.length > 14 ? 4.3 : c.n.length > 11 ? 5 : c.n.length > 8 ? 5.7 : 6.2;\n    const st = GKSTARS.map((d, i) => `<path class=\"${i < r ? 'on' : ''}\" d=\"${d}\"/>`).join('');\n    const ob = (v, dl, k) => `<div class=\"orb ${k}${dl > 0 ? ' up' : dl < 0 ? ' dn' : ''}\">${v + (dl || 0)}</div>`;\n    return `<div class=\"${cls} tpl p${c.pos}\" data-id=\"${c.id}\" style=\"${phOf(c)}\"><div class=\"in\">${c.fl == 'c' ? '<div class=\"two\"></div>' : ''}<div class=\"tsv\"></div>${r == 2 || r == 3 || r == 5 ? `<div class=\"twm w${r}\"></div>` : ''}<svg class=\"tst\" viewBox=\"0 0 573.75 717.75\" preserveAspectRatio=\"none\" aria-hidden=\"true\">${st}</svg><div class=\"tpos\">${c.pos}</div>${logoOf(c.tm) ? `<img class=\"tlogo\" alt=\"\" src=\"${logoOf(c.tm)}\">` : ''}${ob(c.d, o.dd, 'od')}${ob(c.a, o.da, 'oa')}<div class=\"tnm\" style=\"--nfs:${nfs}cqw\">${c.n}</div><div class=\"tsb\">${c.pl} - ${c.tm}</div></div>${pop}</div>`;\n  }\n  if (c.t == 'T') {\n    const r = c.r || 1, T = TACT[c.n] || {}, et = T.s || '', L = et.length;\n    const efs = L > 50 ? 2.3 : L > 34 ? 2.6 : 2.9, nfs = c.n.length > 16 ? 4.3 : c.n.length > 12 ? 5 : 6;\n    const st = GKSTARS.map((d, i) => `<path class=\"${i < r ? 'on' : ''}\" d=\"${d}\"/>`).join('');\n    const ob = (v, dl, k) => `<div class=\"orb ${k}${dl > 0 ? ' up' : dl < 0 ? ' dn' : ''}\">${v + (dl || 0)}</div>`;\n    return `<div class=\"${cls} tpl\" data-id=\"${c.id}\" title=\"${c.n} — tactique, attaque ${c.a}, défense ${c.d}. ${RAR[r]}. Effet : ${T.t || ''}\"><div class=\"in\"><div class=\"tico\">${TICO}</div>${c.fl == 'c' ? '<div class=\"two\"></div>' : ''}<div class=\"tsv\"></div>${r == 2 || r == 3 || r == 5 ? `<div class=\"twm w${r}\"></div>` : ''}<svg class=\"tst\" viewBox=\"0 0 573.75 717.75\" preserveAspectRatio=\"none\" aria-hidden=\"true\">${st}</svg><div class=\"tpos\">TAC</div>${ob(c.d, o.dd, 'od')}${ob(c.a, o.da, 'oa')}<div class=\"teff\" style=\"--efs:${efs}cqw\">${et}</div><div class=\"tnm\" style=\"--nfs:${nfs}cqw\">${c.n}</div></div>${pop}</div>`;\n  }\n  const tip = `${c.n} — attaque ${c.a}, défense ${c.d}` + (c.t == 'J' ? `, ${POS[c.pos].toLowerCase()}, ${c.tm} (${c.pl})` : `, tactique. Effet : ${(TACT[c.n] || {}).t || ''}`) + (o.da || o.dd ? `. Modifié : ${o.da ? (o.da > 0 ? '+' : '') + o.da + ' attaque' : ''}${o.dd ? (o.dd > 0 ? '+' : '') + o.dd + ' défense' : ''}${o.why ? ' (' + o.why + ')' : ''}` : '');\n  const mid = c.t == 'J' ? `<div class=\"ps\" style=\"color:${PCOL[c.pos]}\">${c.pos}</div>` : `<div class=\"ico\">${TICO}</div>`;\n  return `<div class=\"${cls}\" data-id=\"${c.id}\" style=\"${c.t == 'J' ? phOf(c) : ''}\" title=\"${tip}\"><div class=\"in\">${vb(c.a, o.da, 'va')}${vb(c.d, o.dd, 'vd')}${mid}<div class=\"nm\">${c.n}</div>${sub}</div>${pop}</div>`;\n}\n// options d'affichage d'une carte posée dans un banc (valeur du rôle modifiée par les synergies)\nfunction benchOpt(c, bench, gk, role, key, dl, ev) {\n  const b = ev ? (ev.d.get(c.id) || 0) : bonusOf(c, bench, gk), w = whyOf(c, bench, gk);\n  const o = role == 'A' ? { da: b, role } : { dd: b, role };\n  if (w.b) { o.why = `+${w.b}, même ${w.k} que ${w.w}`; if (key && isNew(key + ':' + c.id + ':' + w.b + w.w)) { o.pop = `+${w.b} ${w.k}`; o.dl = dl || 0; } }\n  return o;\n}\nfunction gkOpt(gk, cards, key) { // le gardien s'anime quand il crée un nouveau lien\n  const ln = cards.filter(c => c.t == 'J' && linkV(c, gk) > 0 && whyOf(c, cards, gk).w == 'le gardien');\n  if (!ln.length || !key) return {};\n  const k = key + ':gk:' + ln.map(c => c.id).sort().join(',');\n  return isNew(k) ? { pop: 'lien', dl: 0 } : {};\n}\n\n/* ---------- état ---------- */\nlet G, AILV = 'normal', MYDECK = 'Snow Kids', GKSLOT = 0;\nfunction newPlayer(name, tm) { const D = mkStarter(tm, GKSLOT); return { name, deck: D.deck, gk: D.gk, tms: D.tms, hand: [], disc: [], goals: [], bench: [], hs: 5, pd: 0 }; }\nconst hasJ = a => a.some(c => c.t == 'J');\nconst scored = i => G.p[1 - i].goals.length; // buts marqués par i\n\nfunction log(t) { G.log.unshift(t); $('log').innerHTML = G.log.slice(0, 60).map(x => `<div>${x}</div>`).join(''); }\nfunction say(h) { $('msg').innerHTML = h; }\n\n/* ---------- rendu ---------- */\nfunction sideHTML(i) {\n  const P = G.p[i], role = G.phase == 'idle' ? '' : (G.att == i ? 'A' : 'D');\n  const showFace = G.reveal;\n  const bk = showFace ? 'b' + G.turn + '-' + i : null;\n  const O = G.p[1 - i], ev = role ? sideEval(P, P.bench, role, O, O.bench) : null;\n  const bench = P.bench.map((c, j) => cardHTML(c, { ...benchOpt(c, P.bench, P.gk, role, bk, 350 + j * 120, ev), back: !showFace, flip: showFace && G.justRevealed })).join('');\n  const parts = ev ? [ev.syn ? `+${ev.syn} synergies` : '', ev.e && ev.eff ? `+${ev.eff} gardien` : '', ev.tac ? `+${ev.tac} tactiques` : '', ev.malT ? `<span style=\"color:var(--bad)\">−${ev.malT} malus</span>` : ''].filter(Boolean) : [];\n  const tt = showFace && P.bench.length ? (role == 'A' ? `<span style=\"color:var(--atk)\">Attaque <b>${ev.tot}</b></span>` : `<span style=\"color:var(--def)\">Défense <b>${ev.tot}</b></span>`) + (parts.length ? ` <span style=\"color:var(--ok)\">dont ${parts.join(', ')}</span>` : '') : '';\n  const gkOn = showFace ? !!(ev && ev.e) : (i == 0 && G.pick ? !!effOn(P, previewBench()) : false);\n  const goals = [0, 1, 2].map(k => P.goals[k] !== undefined ? `<div class=\"slot on${isNew('but:' + i + ':' + k) ? ' nw' : ''}\"></div>` : `<div class=\"slot\">${k + 1}</div>`).join('');\n  return `<div class=\"col\"><div class=\"zl\">Gardien</div>${cardHTML(P.gk, { ...(i == 0 && G.pick ? gkOpt(P.gk, previewBench(), 'h') : showFace ? gkOpt(P.gk, P.bench, bk) : {}), on: gkOn, ...(gkOn && isNew('gkfx' + (showFace ? bk : 'h') + i) ? { pop: 'EFFET', dl: 300 } : {}) })}</div>\n  <div class=\"bench\">${role ? `<span class=\"role ${role}\">${role == 'A' ? 'Attaque' : 'Défense'}</span>` : ''}<div class=\"zl\">Banc${i == 1 ? ' — IA' : ''}</div><div class=\"cards\">${bench || '<span class=\"zl\" style=\"opacity:.5\">vide</span>'}</div><div class=\"tot\">${tt}</div></div>\n  <div class=\"col\"><div class=\"zl\">Buts encaissés</div><div class=\"goals\">${goals}</div>\n    <div class=\"stk\">\n      <div><div class=\"zl\">Défausse</div><div class=\"slot stack ${P.disc.length ? 'has' : ''}\" data-disc=\"${i}\"><span class=\"n\">${P.disc.length}</span></div></div>\n      <div><div class=\"zl\">Deck</div><div class=\"slot stack ${P.deck.length ? 'has' : ''}\"><span class=\"n\">${P.deck.length}</span></div></div>\n    </div></div>`;\n}\nfunction render() {\n  if (!G) return;\n  G.cur = new Set();\n  $('sideAi').innerHTML = sideHTML(1);\n  $('sideMe').innerHTML = sideHTML(0);\n  $('oppHand').innerHTML = G.p[1].hand.map(() => '<div class=\"card back\"></div>').join('') + `<span class=\"zl\" style=\"margin-left:6px\">main IA : ${G.p[1].hand.length}</span>`;\n  const me = G.p[0], role = G.att == 0 ? 'A' : 'D';\n  const h = $('hand');\n  h.className = 'hand' + (G.pick ? '' : ' locked');\n  const prev = previewBench();\n  const pev = sideEval(me, prev, role, null);\n  h.innerHTML = me.hand.map(c => G.sel.has(c.id) ? cardHTML(c, { ...benchOpt(c, prev, me.gk, role, 'h', 0, pev), sel: true }) : cardHTML(c, { role })).join('');\n  $('scMe').textContent = scored(0); $('scAi').textContent = scored(1);\n  document.querySelectorAll('[data-disc]').forEach(el => el.onclick = () => showDisc(+el.dataset.disc));\n  [['sideMe', 0], ['sideAi', 1]].forEach(([id, i]) => { const el = $(id).querySelector('[data-gk]'); if (el) el.onclick = () => showGk(i); });\n  // éclairs : un pour chaque nouvelle paire de cartes liées (banc + gardien)\n  const ctx = [];\n  if (G.pick) ctx.push(['h', [...previewBench(), me.gk], 0]);\n  if (G.reveal) G.p.forEach((P, i) => P.bench.length && ctx.push(['b' + G.turn + '-' + i, [...P.bench, P.gk], 420]));\n  for (const [key, cs, dl] of ctx) {\n    const J = cs.filter(c => c.t == 'J' || c.t == 'G');\n    for (let x = 0; x < J.length; x++) for (let y = x + 1; y < J.length; y++) {\n      const v = linkV(J[x], J[y]);\n      if (v && !(J[x].t == 'G' && J[y].t == 'G') && isNew(key + ':pair:' + J[x].id + '-' + J[y].id)) G.bolts.push({ a: J[x].id, b: J[y].id, v, dl });\n    }\n  }\n  if (G.bolts.length) { const bs = G.bolts; G.bolts = []; requestAnimationFrame(() => bs.forEach((b, k) => setTimeout(() => bolt(b), b.dl + k * 90))); }\n  G.justRevealed = false;\n  G.prev = G.cur;\n  updBtn();\n}\nfunction previewBench() { // cartes déjà posées (égalité) + cartes sélectionnées\n  if (!G.pick) return [];\n  const me = G.p[0];\n  return [...(G.pick == 1 ? me.bench : []), ...me.hand.filter(c => G.sel.has(c.id))];\n}\nfunction updBtn() {\n  const b = $('bAct');\n  if (!G.pick) { b.hidden = true; return; }\n  b.hidden = false;\n  const sel = G.p[0].hand.filter(c => G.sel.has(c.id));\n  const pv = previewBench(), t = pv.length ? ` · total ${sideEval(G.p[0], pv, G.att == 0 ? 'A' : 'D', null).tot}` : '';\n  if (G.pick == 3) { b.textContent = `Poser face cachée (${sel.length}/3)${t}`; b.disabled = !(sel.length == 3 && hasJ(sel)); return; }\n  b.textContent = `Poser la carte (${sel.length}/1)${t}`; b.disabled = sel.length != 1;\n}\n$('hand').addEventListener('click', e => {\n  const el = e.target.closest('.card'); if (!el || !G.pick) return;\n  const id = +el.dataset.id;\n  if (G.sel.has(id)) G.sel.delete(id);\n  else { if (G.pick == 1) G.sel.clear(); if (G.sel.size < G.pick) G.sel.add(id); }\n  render();\n});\nlet pickResolve = null;\n$('bAct').onclick = () => { if (pickResolve) { const r = pickResolve; pickResolve = null; r(); } };\nfunction humanPick(n, text) {\n  G.pick = n; G.sel = new Set(); say(text); render();\n  return new Promise(res => pickResolve = () => {\n    const me = G.p[0], out = me.hand.filter(c => G.sel.has(c.id));\n    me.hand = me.hand.filter(c => !G.sel.has(c.id)); G.pick = 0; G.sel = new Set(); res(out);\n  });\n}\n\n/* ---------- IA ---------- */\nconst AIV = { draw: 9, pdisc: 10, recov1: 6, recovhand: 6, recovnow: 8, nextatk: 6, antimalus: 3, nosyn: 10, oppbest: 6, oppA: 8 }, DONLY = ['oppA', 'nextatk', 'recov1', 'recovhand'];\nfunction aiPick3(P, role) {\n  const h = P.hand, k = role == 'A' ? 'a' : 'd';\n  let best = null;\n  for (let i = 0; i < h.length; i++) for (let j = i + 1; j < h.length; j++) for (let l = j + 1; l < h.length; l++) {\n    const cs = [h[i], h[j], h[l]]; if (!hasJ(cs)) continue;\n    const v = AILV == 'facile' ? Math.random() : sideEval(P, cs, role, null).tot + cs.reduce((s, c) => s + (c.t == 'T' && AIV[c.k] && (!DONLY.includes(c.k) || role == 'D') ? AIV[c.k] : 0), 0);\n    if (!best || v > best.v) best = { v, cs };\n  }\n  P.hand = h.filter(c => !best.cs.includes(c)); return best.cs;\n}\nfunction aiPick1(P, role) {\n  if (!P.hand.length) return null;\n  const k = role == 'A' ? 'a' : 'd';\n  const sc = c => sideEval(P, [...P.bench, c], role, null).tot;\n  const c = AILV == 'facile' ? P.hand[rnd(0, P.hand.length - 1)] : P.hand.reduce((m, c) => sc(c) > sc(m) ? c : m);\n  P.hand = P.hand.filter(x => x != c); return c;\n}\n\n/* ---------- modales ---------- */\nfunction modal(html) { $('box').innerHTML = html; $('mo').hidden = false; }\nfunction closeModal() { $('mo').hidden = true; }\n$('mo').addEventListener('click', e => { if (e.target.id == 'mo' && G && !G.modalLock) closeModal(); });\nfunction showGk(i) {\n  if (G.modalLock) return;\n  const g = G.p[i].gk;\n  modal(`<h2>${g.n} — gardien ${g.slot ? 'titulaire' : 'remplaçant'}</h2><div style=\"display:flex;gap:14px;align-items:flex-start;flex-wrap:wrap\"><div style=\"--cw:110px\">${cardHTML(g)}</div><p style=\"flex:1;min-width:200px\">${g.tm} · ${g.pl}<br><br>${effText(g)}<br><br><span class=\"zl\" style=\"text-align:left\">L’effet s’active à chaque duel où la condition est remplie sur votre banc (cartes posées pour une égalité comprises).</span></p></div><div class=\"row\"><button onclick=\"closeModal()\">Fermer</button></div>`);\n}\nfunction showDisc(i) {\n  if (G.modalLock) return;\n  const P = G.p[i];\n  modal(`<h2>Défausse — ${i ? 'IA' : 'vous'} (${P.disc.length})</h2><div class=\"grid\">${P.disc.map(c => cardHTML(c)).join('') || '<p>Vide.</p>'}</div><div class=\"row\"><button onclick=\"closeModal()\">Fermer</button></div>`);\n}\nfunction pickFromDisc(toHand, title, onlyJ) {\n  const P = G.p[0];\n  return new Promise(res => {\n    let sel = null; G.modalLock = true;\n    const draw = () => modal(`<h2>${title || 'Attaque bloquée !'}</h2><p>${onlyJ ? 'Choisissez une carte Joueur de votre défausse : elle revient dans votre main.' : toHand ? 'Choisissez une carte de votre défausse : elle va directement dans votre main.' : 'Choisissez une carte de votre défausse : elle retourne dans votre deck, qui est ensuite mélangé.'}</p><div class=\"grid\" id=\"dg\">${P.disc.filter(c => !onlyJ || c.t == 'J').map(c => cardHTML(c, { sel: sel && sel.id == c.id })).join('')}</div><div class=\"row\"><button id=\"dOk\" ${sel ? '' : 'disabled'}>${toHand ? 'Prendre en main' : 'Remettre dans le deck'}</button></div>`);\n    draw();\n    $('box').onclick = e => {\n      const el = e.target.closest('.card');\n      if (el && el.dataset.id) { sel = P.disc.find(c => c.id == +el.dataset.id); draw(); }\n      if (e.target.id == 'dOk' && sel) { G.modalLock = false; $('box').onclick = null; closeModal(); res(sel); }\n    };\n  });\n}\nconst RULES = `<h2>Règles du duel</h2><ol>\n<li><b>Mise en place.</b> Deck de 40 cartes plus le gardien, dont au moins 20 cartes Joueur et 3 exemplaires au maximum par carte. Le gardien est posé d’office. Un pile ou face désigne le premier attaquant.</li>\n<li><b>Début de tour.</b> Si votre deck ne contient plus aucun joueur, vous perdez. Sinon vous complétez votre main à 5 cartes (deck vide au moment de piocher : défaite). Sans joueur en main, elle est remélangée jusqu’à en obtenir un. Moins de 3 cartes en main : défaite.</li>\n<li><b>Pose.</b> Chacun pose 3 cartes face cachée, dont au moins un joueur. On révèle : l’attaquant additionne les valeurs <b style=\"color:var(--atk)\">roses (attaque)</b>, le défenseur les <b style=\"color:var(--def)\">bleues (défense)</b>.</li>\n<li><b>Synergies.</b> Une carte Joueur liée à une autre carte Joueur du banc ou à votre gardien gagne un bonus sur la valeur qui compte : <b>+5</b> si même planète ou même équipe, <b>+10</b> si même planète et même équipe. Seul le meilleur lien compte, sans cumul. Une valeur modifiée s’affiche <b style=\"color:var(--ok)\">en vert</b> (bonus) ou <b style=\"color:#ff4d5e\">en rouge</b> (malus).</li>\n<li><b>Gardiens.</b> Chaque gardien a un effet qui s’active à chaque duel où votre banc contient assez de joueurs de son équipe (ou de sa planète). Touchez un gardien pour lire son effet. Les remplaçants des decks de départ reçoivent un renfort calculé selon la force du deck.</li>\n<li><b>Tactiques.</b> Chaque carte Tactique a des valeurs faibles mais un effet, appliqué dès qu’elle est jouée (texte sur la carte). Toutes les cartes du même nom ont exactement les mêmes valeurs et le même effet.</li>\n<li><b>Égalité.</b> Chacun pose une carte de plus, face cachée, jusqu’à départager. Plus de carte en main : confrontation perdue.</li>\n<li><b>But.</b> Le défenseur place la carte du dessus de son deck (ou de sa défausse) dans sa zone de but.</li>\n<li><b>Blocage.</b> Le banc part à la défausse, puis le défenseur remet une carte de sa défausse dans son deck et le mélange.</li>\n<li><b>Fin de tour.</b> Le banc part à la défausse et les rôles s’inversent.</li>\n<li><b>Victoire.</b> 3 buts. Si le premier attaquant y arrive, l’autre garde sa dernière attaque. 3-3 : mort subite.</li>\n<li><b>Double défaite.</b> Plus de buts marqués gagne, sinon mort subite : chacun tire 3 cartes au hasard parmi toutes les siennes, le plus gros total d’attaque l’emporte.</li></ol>\n<p class=\"zl\" style=\"text-align:left\">Les valeurs des joueurs dépendent de leur note générale au moment où le jeu de cartes a été activé.</p><div class=\"row\"><button class=\"ghost\" onclick=\"rulesTour(0)\">Avec Clamp</button><button onclick=\"rulesClose()\">Compris</button></div>`;\n\n// Règles racontées par Clamp, étape par étape (comme la visite guidée de la carrière).\nconst RSTEPS = [\n  ['Bienvenue au duel !', 'Salut ! Moi, c’est Clamp. Les cartes, c’est ma petite passion, alors je t’explique tout en {N} étapes. Tu peux avancer avec « Suivant », revenir en arrière, ou tout voir d’un coup avec « Toutes les règles ».'],\n  ['La mise en place', 'Ton deck compte 40 cartes plus ton gardien, dont au moins 20 cartes Joueur, et jamais plus de 3 exemplaires d’une même carte. Ton gardien est posé d’office, à côté du terrain. Un pile ou face désigne qui attaque en premier.'],\n  ['Le début du tour', 'Au début de chaque tour, on vérifie ton deck : s’il ne contient plus aucun joueur, c’est perdu. Sinon, tu complètes ta main à 5 cartes. Si ton deck est vide au moment de piocher, c’est perdu aussi. Pas de joueur en main ? Elle est remélangée jusqu’à en avoir un. Et avec moins de 3 cartes en main, c’est la défaite.'],\n  ['La pose', 'Chacun pose 3 cartes face cachée, dont au moins un joueur. Puis on révèle tout ! L’attaquant additionne ses valeurs <b style=\"color:var(--atk)\">roses (attaque)</b>, le défenseur ses valeurs <b style=\"color:var(--def)\">bleues (défense)</b>. Le plus gros total l’emporte.'],\n  ['Les synergies', 'Mon conseil préféré : joue des cartes qui vont ensemble ! Une carte Joueur liée à une autre carte Joueur du banc, ou à ton gardien, gagne <b>+5</b> si elles ont la même planète ou la même équipe, et <b>+10</b> si elles ont les deux. Seul le meilleur lien compte, sans cumul. Une valeur modifiée s’affiche <b style=\"color:var(--ok)\">en vert</b> (bonus) ou <b style=\"color:var(--bad)\">en rouge</b> (malus).'],\n  ['Les gardiens', 'Chaque gardien a un effet spécial, qui s’active quand ton banc contient assez de joueurs de son équipe (ou de sa planète). Touche ton gardien pour lire son effet. Les remplaçants des decks de départ reçoivent en plus un renfort calculé selon la force du deck.'],\n  ['Les tactiques', 'Les cartes Tactique ont des valeurs faibles, mais un effet appliqué dès qu’elles sont jouées : le texte est écrit sur la carte. Toutes les cartes du même nom ont exactement les mêmes valeurs et le même effet.'],\n  ['L’égalité', 'Égalité ? Chacun pose une carte de plus, face cachée, jusqu’à ce qu’on puisse départager. Si tu n’as plus de carte en main, tu perds la confrontation.'],\n  ['Le but', 'Si l’attaque passe, c’est BUT ! Le défenseur place la carte du dessus de son deck (ou de sa défausse) dans sa zone de but.'],\n  ['Le blocage', 'Si la défense tient, le banc part à la défausse, puis le défenseur récupère une carte de sa défausse, la remet dans son deck et le mélange. Bien défendre, c’est aussi reconstruire !'],\n  ['La fin du tour', 'À la fin du tour, le banc part à la défausse et les rôles s’inversent : l’attaquant défend, le défenseur attaque.'],\n  ['La victoire', 'Le premier à 3 buts gagne. Si le premier attaquant y arrive, l’autre garde quand même sa dernière attaque. À 3-3, c’est la mort subite. Et si les deux joueurs perdent en même temps, celui qui a marqué le plus de buts gagne ; sinon, mort subite : chacun tire 3 cartes au hasard parmi toutes les siennes, et le plus gros total d’attaque l’emporte.'],\n  ['Raretés et Légendes', 'Les raretés (Classique, Chromatique, Prismatique, Mythique) changent l’allure de la carte, pas ses valeurs. Seules les cartes Légende sont plus fortes : un joueur Légende gagne +5 en attaque et en défense, un gardien Légende active son effet avec un joueur de moins. Les valeurs des joueurs dépendent de leur note générale au moment où le jeu de cartes a été activé.'],\n  ['À toi de jouer !', 'Voilà, tu sais tout ! Lance un duel depuis l’Accueil, et n’oublie pas : chaque match de ton club te rapporte un booster. Tes succès, ton Collector et tes Légendes se suivent dans la Galerie de la carrière. Bonne chance, manager !'],\n];\nconst CLAMP = `<div class=\"cla\"><svg viewBox=\"0 0 100 100\" aria-hidden=\"true\"><rect width=\"100\" height=\"100\" fill=\"#3a1a6a\"/><circle cx=\"50\" cy=\"42\" r=\"20\" fill=\"#d9a066\"/><path d=\"M26 48l-10-22 18 8 6-20 14 14 14-14 6 20 18-8-10 22z\" fill=\"#9a9aa4\"/><path d=\"M10 100c4-26 20-36 40-36s36 10 40 36z\" fill=\"#4b2d6e\"/></svg><img src=\"img/clamp.jpg\" alt=\"Clamp\" onerror=\"this.remove()\"></div>`;\nfunction rulesClose() { G ? closeModal() : startScreen(); }\nfunction rulesTour(i) {\n  i = Math.max(0, Math.min(RSTEPS.length - 1, i | 0));\n  const [t, x] = RSTEPS[i], N = RSTEPS.length, last = i == N - 1;\n  modal(`<div class=\"clh\">${CLAMP}<div class=\"cln\"><b>Clamp</b><small>Règles du duel · étape ${i + 1}/${N}</small></div></div>\n    <h2>${t}</h2><p class=\"clt\">${x.replace('{N}', N)}</p>\n    <div class=\"cld\">${RSTEPS.map((_, k) => `<i class=\"${k == i ? 'on' : k < i ? 'pa' : ''}\" onclick=\"rulesTour(${k})\"></i>`).join('')}</div>\n    <div class=\"row\"><button class=\"ghost\" onclick=\"rulesClose()\">Fermer</button>${i ? `<button class=\"ghost\" onclick=\"rulesTour(${i - 1})\">← Précédent</button>` : ''}<button class=\"ghost\" onclick=\"modal(RULES)\">Toutes les règles</button><button class=\"${last ? '' : 'p'}\" onclick=\"${last ? 'rulesClose()' : `rulesTour(${i + 1})`}\">${last ? 'Compris !' : 'Suivant →'}</button></div>`);\n}\n$('bRules').onclick = () => { if (!G || !G.modalLock) rulesTour(0); };\n\n/* ---------- déroulement ---------- */\nfunction resetBoard() { $('sideAi').innerHTML = ''; $('sideMe').innerHTML = ''; $('hand').innerHTML = ''; $('oppHand').innerHTML = ''; $('log').innerHTML = ''; say(''); $('bAct').hidden = true; }\nfunction startScreen() {\n  if (!G || G.phase != 'play') { G = null; resetBoard(); }\n  if (!ST.deckStart) return starterScreen();\n  goHub();\n}\n// Un duel est-il en cours ? (la partie grise alors son bouton « Continuer »)\nwindow.duelOn = () => !!(G && !G.done);\nfunction duelPing() { try { H.duel && H.duel(); } catch (e) {} }\nasync function coin() {\n  const D0 = ST.decks.find(d => d.id == ST.active), P0 = deckPlayer('Vous', D0), oth = TEAMS.map(t => t[0]).filter(t => t != ST.deckStart);\n  G = { cur: new Set(), prev: new Set(), bolts: [], p: [P0, newPlayer('IA', oth[rnd(0, oth.length - 1)])], att: 0, first: 0, turn: 0, attacks: [0, 0], phase: 'idle', sel: new Set(), pick: 0, reveal: false, log: [], modalLock: true };\n  const f = Math.random() < .5 ? 0 : 1; G.first = G.att = f;\n  duelPing();\n  modal(`<h2>Pile ou face</h2><div class=\"coin spin\"><div id=\"cn\">?</div></div><p id=\"ct\" style=\"text-align:center\">…</p><p style=\"text-align:center\" class=\"zl\">Votre deck : ${G.p[0].tms.join(' + ')} · IA : ${G.p[1].tms.join(' + ')}</p>`);\n  render();\n  await wait(1000);\n  $('cn').textContent = f == 0 ? 'VOUS' : 'IA';\n  $('ct').innerHTML = f == 0 ? '<b>Vous gagnez le pile ou face :</b> vous attaquez en premier.' : '<b>L’IA gagne le pile ou face :</b> elle attaque en premier. Vous aurez toujours votre attaque de réponse.';\n  log(`Votre deck : ${G.p[0].tms.join(' + ')}. Deck de l’IA : ${G.p[1].tms.join(' + ')}.`);\n  log(f == 0 ? 'Pile ou face : vous attaquez en premier.' : 'Pile ou face : l’IA attaque en premier.');\n  await wait(1700);\n  G.modalLock = false; closeModal(); G.phase = 'play';\n  loop();\n}\n\nfunction startChecks(i) {\n  const P = G.p[i];\n  if (!hasJ(P.deck)) return 'plus aucun joueur dans le deck';\n  const size = P.hs || 5; P.hs = 5;\n  const need = size - P.hand.length;\n  if (need > 0 && !P.deck.length) return 'deck vide au moment de piocher';\n  for (let k = 0; k < need && P.deck.length; k++) P.hand.push(P.deck.pop());\n  if (size != 5) log(`${i ? 'IA' : 'Vous'} : main de ${size} cartes ce tour (effet de gardien).`);\n  if (P.pd && P.hand.length > 3) { const c = P.hand.reduce((m, x) => x.a + x.d > m.a + m.d ? x : m); P.hand = P.hand.filter(x => x != c); P.disc.push(c); log(`${i ? 'L’IA défausse' : 'Vous défaussez'} ${c.n} (effet du gardien adverse).`); }\n  P.pd = 0;\n  if (!hasJ(P.hand) && !hasJ(P.deck)) return 'plus aucun joueur disponible';\n  let m = 0;\n  while (!hasJ(P.hand) && m < 300) { const n = P.hand.length; P.deck.push(...P.hand); P.hand = []; shuffle(P.deck); for (let k = 0; k < n; k++) P.hand.push(P.deck.pop()); m++; }\n  if (m) log(`${i ? 'IA' : 'Vous'} : main sans joueur, remélangée ${m} fois.`);\n  if (P.hand.length < 3) return 'moins de 3 cartes en main';\n  return null;\n}\n\nasync function loop() {\n  while (G && G.phase == 'play') {\n    G.turn++;\n    const L = [startChecks(0), startChecks(1)];\n    render();\n    if (L[0] || L[1]) {\n      if (L[0] && L[1]) {\n        log(`Double défaite (vous : ${L[0]} ; IA : ${L[1]}).`);\n        const s0 = scored(0), s1 = scored(1);\n        if (s0 != s1) return finish(s0 > s1 ? 0 : 1, `Les deux joueurs ne peuvent plus jouer : victoire aux buts marqués.`);\n        return sudden('Les deux joueurs ne peuvent plus jouer, à égalité de buts.');\n      }\n      const l = L[0] ? 0 : 1;\n      return finish(1 - l, `${l ? 'L’IA' : 'Vous'} : ${L[l]}.`);\n    }\n    const A = G.att, D = 1 - A, me = G.p[0], ai = G.p[1];\n    G.reveal = false; me.bench = []; ai.bench = [];\n    log(`— Tour ${G.turn} : ${A == 0 ? 'vous attaquez' : 'vous défendez'}.`);\n    // pose\n    ai.bench = aiPick3(ai, A == 1 ? 'A' : 'D');\n    render();\n    me.bench = await humanPick(3, A == 0\n      ? `<span class=\"big\" style=\"color:var(--atk)\">Vous attaquez</span>Choisissez 3 cartes (dont au moins un joueur). Seules les valeurs <b style=\"color:var(--atk)\">roses</b> comptent.`\n      : `<span class=\"big\" style=\"color:var(--def)\">Vous défendez</span>Choisissez 3 cartes (dont au moins un joueur). Seules les valeurs <b style=\"color:var(--def)\">bleues</b> comptent.`);\n    say('Les deux bancs sont prêts…'); render(); await wait(700);\n    G.reveal = true; G.justRevealed = true; render();\n    const evA = () => sideEval(G.p[A], G.p[A].bench, 'A', G.p[D], G.p[D].bench), evD = () => sideEval(G.p[D], G.p[D].bench, 'D', G.p[A], G.p[A].bench);\n    let EA = evA(), ED = evD(), sa = EA.tot, sd = ED.tot;\n    achDuelTurn(A == 0 ? EA : ED);\n    if (G.p[A].nb) log(`Bonus de contre-attaque : +${G.p[A].nb} (${A ? 'IA' : 'vous'}).`);\n    [[A, EA], [D, ED]].forEach(([i, E]) => E.e && log(`Effet du gardien ${i ? 'de l’IA' : 'vous'} (${G.p[i].gk.n}) : ${effText(G.p[i].gk, true)}.`));\n    say(`<span class=\"big gold\">${sa} contre ${sd}</span>Attaque ${A == 0 ? 'vous' : 'IA'} contre défense ${D == 0 ? 'vous' : 'IA'}`);\n    await wait(4000);\n    let out = null, n = 0;\n    while (sa == sd) {\n      if (EA.e && EA.e.k == 'tiewin') { out = 'goal'; log('Égalité gagnée grâce au gardien de l’attaquant.'); break; }\n      if (ED.e && ED.e.k == 'tiewin') { out = 'block'; log('Égalité gagnée grâce au gardien du défenseur.'); break; }\n      n++; log(`Égalité ${sa}-${sd} : carte supplémentaire (${n}).`);\n      const aiCard = aiPick1(ai, A == 1 ? 'A' : 'D');\n      let myCard = null;\n      if (me.hand.length) {\n        G.reveal = true;\n        [myCard] = await humanPick(1, `<span class=\"big gold\">Égalité ${sa}-${sd} !</span>Posez une carte de plus, face cachée.`);\n      }\n      const ca = A == 0 ? myCard : aiCard, cd = D == 0 ? myCard : aiCard;\n      if (myCard) me.bench.push(myCard); if (aiCard) ai.bench.push(aiCard);\n      G.justRevealed = true; render(); await wait(900);\n      if (!ca) { out = 'block'; log('L’attaquant n’a plus de carte : attaque bloquée.'); break; }\n      if (!cd) { out = 'goal'; log('Le défenseur n’a plus de carte : but.'); break; }\n      EA = evA(); ED = evD(); sa = EA.tot; sd = ED.tot;\n      say(`<span class=\"big gold\">${sa} contre ${sd}</span>`); await wait(3200);\n    }\n    out = out || (sa > sd ? 'goal' : 'block');\n    if (out == 'block' && D == 0) TS().blk++;\n    G.attacks[A]++;\n    const PA = G.p[A], PD = G.p[D], BA = PA.bench.slice(), BD = PD.bench.slice();\n    PA.nb = 0;\n    if (out == 'goal') {\n      const gc = ED.e && ED.e.k == 'goaldisc' && PD.disc.length ? PD.disc.pop() : PD.deck.length ? PD.deck.pop() : PD.disc.length ? PD.disc.pop() : null;\n      PD.goals.push(gc); G.maxDef = Math.max(G.maxDef || 0, scored(1) - scored(0));\n      log(`BUT pour ${A == 0 ? 'vous' : 'l’IA'} (${sa} contre ${sd}). Score ${scored(0)}-${scored(1)}.`);\n      say(`<span class=\"big goal\">BUT !</span>${A == 0 ? 'Vous marquez' : 'L’IA marque'} — ${sa} contre ${sd}.${gc ? '' : ''}`);\n      PA.disc.push(...PA.bench); PD.disc.push(...PD.bench); PA.bench = []; PD.bench = [];\n      render(); await wait(1600);\n    } else {\n      log(`Attaque bloquée par ${D == 0 ? 'vous' : 'l’IA'} (${sa} contre ${sd}).`);\n      say(`<span class=\"big block\">ARRÊT !</span>${D == 0 ? 'Vous bloquez' : 'L’IA bloque'} — ${sa} contre ${sd}.`);\n      await wait(1200);\n      PA.disc.push(...PA.bench); PD.disc.push(...PD.bench); PA.bench = []; PD.bench = [];\n      render();\n      const tkD = kk => BD.filter(c => c.t == 'T' && c.k == kk).length;\n      const nrec = (ED.e && ED.e.k == 'recov2' ? 2 : 1) + tkD('recov1') + tkD('recovhand'), toHand = (ED.e && ED.e.k == 'recovhand') || tkD('recovhand') > 0;\n      for (let q = 0; q < nrec && PD.disc.length; q++) {\n        let c;\n        if (D == 0) c = await pickFromDisc(toHand);\n        else c = PD.disc.reduce((m, x) => ((x.t == 'J') * 1000 + x.a + x.d) > ((m.t == 'J') * 1000 + m.a + m.d) ? x : m);\n        PD.disc = PD.disc.filter(x => x != c);\n        if (toHand) PD.hand.push(c); else { PD.deck.push(c); shuffle(PD.deck); }\n        log(`${D == 0 ? 'Vous remettez' : 'L’IA remet'} ${c.n} dans ${toHand ? 'la main' : 'le deck'}.`);\n      }\n      if (ED.e && ED.e.k == 'blockdraw') PD.hs = 6;\n      const ce = BD.filter(c => c.t == 'T' && c.k == 'nextatk').reduce((s, c) => s + c.x, 0);\n      if (ce) { PD.nb = ce; log(`${D ? 'L’IA prépare' : 'Vous préparez'} une contre-attaque : +${ce} à la prochaine attaque.`); }\n      render(); await wait(500);\n    }\n    for (const [P, O, B] of [[PA, PD, BA], [PD, PA, BD]]) { // effets des tactiques après le duel\n      const has = kk => B.filter(c => c.t == 'T' && c.k == kk);\n      if (has('draw').length) P.hs = Math.max(P.hs, 6);\n      if (has('pdisc').length) { O.pd = 1; log(`${P == G.p[0] ? 'Vous jouez' : 'L’IA joue'} Tacle glissé : défausse adverse au prochain tour.`); }\n      for (let q = 0; q < has('recovnow').length; q++) {\n        if (!P.disc.some(c => c.t == 'J')) break;\n        let c;\n        if (P == G.p[0]) c = await pickFromDisc(true, 'Temps mort', true);\n        else c = P.disc.filter(x => x.t == 'J').reduce((m, x) => x.a + x.d > m.a + m.d ? x : m);\n        P.disc = P.disc.filter(x => x != c); P.hand.push(c);\n        log(`${P == G.p[0] ? 'Vous reprenez' : 'L’IA reprend'} ${c.n} en main (Temps mort).`);\n      }\n    }\n    [[PA, PD, EA, 'A'], [PD, PA, ED, 'D']].forEach(([P, O, E, rl]) => {\n      if (!E.e) return;\n      if (E.e.k == 'draw') P.hs = 6;\n      if (E.e.k == 'xen') { P.hs = 6; O.hs = 4; }\n      if (E.e.k == 'pdisc') O.pd = 1;\n      if (E.e.k == 'pdisc_goal' && rl == 'A' && out == 'goal') O.pd = 1;\n    });\n    // victoire / dernière chance\n    const gA = scored(A), gD = scored(D);\n    if (gA >= 3) {\n      if (G.attacks[D] < G.attacks[A]) {\n        log('Dernière chance : l’autre équipe garde son attaque de réponse.');\n        say(`<span class=\"big gold\">Dernière chance !</span>${D == 0 ? 'Vous avez' : 'L’IA a'} encore une attaque pour égaliser.`);\n        await wait(1800);\n      } else if (gD >= 3) { return sudden('3 buts partout.'); }\n      else return finish(A, '3 buts marqués.');\n    }\n    if (G.attacks[0] == G.attacks[1] && Math.max(scored(0), scored(1)) >= 3) {\n      if (scored(0) != scored(1)) return finish(scored(0) > scored(1) ? 0 : 1, 'La dernière attaque n’a pas suffi.');\n      return sudden('3 buts partout.');\n    }\n    G.att = D;\n  }\n}\n\nasync function sudden(why) {\n  G.phase = 'over'; G.modalLock = true;\n  log('Mort subite : ' + why);\n  let round = 0, w = null, draws;\n  while (w === null) {\n    round++;\n    draws = G.p.map(P => shuffle([...P.deck, ...P.hand, ...P.disc]).slice(0, 3));\n    const t = draws.map((d, i) => tot(d, G.p[i].gk, 'a'));\n    modal(`<h2>Mort subite${round > 1 ? ' — manche ' + round : ''}</h2><p>${why} Chacun tire 3 cartes au hasard parmi toutes les siennes : le plus gros total d’attaque l’emporte.</p>\n      <div class=\"zl\" style=\"text-align:left\">Vous</div><div class=\"grid\">${draws[0].map(c => cardHTML(c, { ...benchOpt(c, draws[0], G.p[0].gk, 'A'), flip: true })).join('')}</div>\n      <div class=\"zl\" style=\"text-align:left\">IA</div><div class=\"grid\">${draws[1].map(c => cardHTML(c, { ...benchOpt(c, draws[1], G.p[1].gk, 'A'), flip: true })).join('')}</div>\n      <p class=\"msg\"><span class=\"big gold\">${t[0]} contre ${t[1]}</span></p>`);\n    await wait(2600);\n    if (t[0] != t[1]) w = t[0] > t[1] ? 0 : 1;\n  }\n  finish(w, 'Mort subite.');\n}\n\nfunction finish(w, why) {\n  G.phase = 'over'; G.pick = 0; G.done = 1; render(); G.modalLock = true; duelPing();\n  achDuelEnd(w, why);\n  log(`Fin de partie : ${w == 0 ? 'victoire' : 'défaite'} (${why})`);\n  say(`<span class=\"big ${w == 0 ? 'gold' : 'goal'}\">${w == 0 ? 'Victoire !' : 'Défaite'}</span>${why}`);\n  modal(`<h2>${w == 0 ? 'Victoire !' : 'Défaite'}</h2><p>${why}</p><p>Score final : <b>${scored(0)} – ${scored(1)}</b> en ${G.turn} tours.</p><p class=\"hint\" style=\"text-align:left\">Les boosters se gagnent avec les matchs de votre club dans la carrière.</p>\n  <div class=\"row\"><button class=\"ghost\" id=\"fSee\">Voir le plateau</button><button class=\"ghost\" id=\"fHub\">Accueil</button><button id=\"fNew\">Rejouer</button></div>`);\n  $('fSee').onclick = () => { G.modalLock = false; closeModal(); };\n  $('fNew').onclick = () => { G.modalLock = false; closeModal(); G = null; resetBoard(); coin(); };\n  $('fHub').onclick = () => { G.modalLock = false; closeModal(); goHub(); };\n}\n\n\n\n/* =================== SUCCÈS, COLLECTOR ET LÉGENDES =================== */\n// Statistiques du jeu de cartes (sauvegardées avec la partie) et succès obtenus.\nconst TS = () => (ST.ts = Object.assign({ duels: 0, wins: 0, packs: 0, myth: 0, gk: 0, blk: 0, l10: 0, w30: 0, sud: 0, cmb: 0, nocl: 0 }, ST.ts || {}));\nconst ACHD = () => (ST.ach = ST.ach || {});\nconst achNew = () => Object.keys(ACHD()).filter(k => ACHD()[k] && ACHD()[k].n).length;\nconst nOwn = () => POOL.filter(c => owned(c)).length;\nconst POOLN = () => POOL.filter(c => c.rs.some(r => r < 5));\nconst canon = () => POOL.filter(c => c.lg || c.ev);\n// Récompenses : cr = crédits pour le club, tt = titre (Galerie et sous le nom du club), lg = carte Légende.\n// Chaque succès : [id, nom, condition, progression () => [actuel, objectif], récompense]\nconst ACHL = [\n  ['d1', 'Premier coup d’envoi', 'Jouer un duel jusqu’au bout.', () => [TS().duels, 1], { cr: 100 }],\n  ['w1', 'Première victoire', 'Gagner un duel.', () => [TS().wins, 1], { cr: 200 }],\n  ['w10', 'Habitué du banc', 'Gagner 10 duels.', () => [TS().wins, 10], { cr: 500, lg: 1 }],\n  ['w25', 'Stratège galactique', 'Gagner 25 duels.', () => [TS().wins, 25], { cr: 1000, tt: 'tc_strat', lg: 1 }],\n  ['w50', 'Maître du duel', 'Gagner 50 duels.', () => [TS().wins, 50], { cr: 2000, tt: 'tc_maitre', lg: 1 }],\n  ['s30', 'Sans appel', 'Gagner un duel 3-0.', () => [TS().w30, 1], { cr: 300, lg: 1 }],\n  ['sud', 'Nerfs d’acier', 'Gagner un duel en mort subite.', () => [TS().sud, 1], { cr: 300 }],\n  ['cmb', 'Remontada cosmique', 'Gagner un duel après avoir été mené de 2 buts.', () => [TS().cmb, 1], { cr: 500, tt: 'tc_remont', lg: 1 }],\n  ['blk', 'Muraille', 'Bloquer 25 attaques.', () => [TS().blk, 25], { cr: 400 }],\n  ['gk', 'Gardien inspiré', 'Déclencher 20 effets de votre gardien.', () => [TS().gk, 20], { cr: 400, lg: 1 }],\n  ['l10', 'Lien parfait', 'Réussir un lien +10 (même planète et même équipe).', () => [TS().l10, 1], { cr: 200 }],\n  ['nocl', 'Grand luxe', 'Gagner un duel avec un banc sans aucune carte Classique.', () => [TS().nocl, 1], { cr: 400 }],\n  ['p10', 'Déballeur', 'Ouvrir 10 boosters.', () => [TS().packs, 10], { cr: 200 }],\n  ['p50', 'Maître des boosters', 'Ouvrir 50 boosters.', () => [TS().packs, 50], { cr: 800, tt: 'tc_boost', lg: 1 }],\n  ['myth', 'Éclat d’or', 'Obtenir une carte Mythique dans un booster.', () => [TS().myth, 1], { cr: 300 }],\n  ['rar', 'Arc-en-ciel', 'Posséder une carte de chaque rareté de booster (Classique, Chromatique, Mythique).', () => [[1, 2, 4].filter(r => POOL.some(c => BS.coll[c.k + '#' + r])).length, 3], { cr: 500, lg: 1 }],\n  ['dk3', 'Architecte', 'Avoir 3 decks valides.', () => [ST.decks.filter(d => deckCheck(d).ok).length, 3], { cr: 200 }],\n  ['c50', 'Collectionneur', 'Posséder 50 cartes différentes.', () => [nOwn(), 50], { cr: 500, lg: 1 }],\n  ['c100', 'Archiviste', 'Posséder 100 cartes différentes.', () => [nOwn(), 100], { cr: 1000, tt: 'tc_coll', lg: 1 }],\n  ['tac', 'Tacticien', 'Posséder toutes les cartes Tactique.', () => [POOL.filter(c => c.t == 'T' && owned(c)).length, POOL.filter(c => c.t == 'T').length], { cr: 500, lg: 1 }],\n  ['all', 'Collection complète', 'Posséder toutes les cartes des boosters.', () => [POOLN().filter(c => owned(c)).length, POOLN().length], { cr: 3000, tt: 'tc_galax', lg: 1 }],\n  ['leg', 'Panthéon', 'Réunir toutes les cartes Légende.', () => [canon().filter(c => BS.coll[c.k + '#5']).length, canon().length], { cr: 2000, tt: 'tc_panth' }],\n];\n// Collector : compléter les joueurs d'une équipe (toutes raretés) débloque les Légendes de ses personnages canon.\nconst COLL = () => TEAMS.map(t => t[0]).map(tm => {\n  const cs = POOL.filter(c => c.t != 'T' && c.tm == tm && !c.ev);\n  return { tm, cs, have: cs.filter(c => owned(c)).length, legs: cs.filter(c => c.lg) };\n});\nconst TTL = { tc_strat: 'Stratège galactique', tc_maitre: 'Maître du duel', tc_remont: 'Roi de la remontada', tc_boost: 'Maître des boosters', tc_coll: 'Archiviste galactique', tc_galax: 'Collectionneur galactique', tc_panth: 'Gardien du Panthéon' };\n// Donne une carte Légende : celle demandée, sinon une au hasard parmi celles qui manquent. Renvoie son nom (ou null si toutes sont déjà là).\nfunction grantLegend(c) {\n  const miss = canon().filter(x => !x.ev && !BS.coll[x.k + '#5']);\n  if (!c || BS.coll[c.k + '#5']) c = miss.length ? miss[rnd(0, miss.length - 1)] : null;\n  if (!c) return null;\n  BS.coll[c.k + '#5'] = 1;\n  return c.n;\n}\nfunction rewardTxt(R, got) {\n  return [R.cr ? `+${R.cr} crédits` : '', R.tt ? `titre « ${TTL[R.tt]} »` : '', got && got.length ? 'Légende : ' + got.join(', ') : R.lg ? 'une carte Légende' : ''].filter(Boolean).join(' · ');\n}\nfunction giveReward(id, name, R, legs) {\n  const got = [];\n  (legs || []).forEach(c => { if (BS.coll[c.k + '#5']) { R = { ...R, cr: (R.cr || 0) + 300 }; return; } const n = grantLegend(c); if (n) got.push(n); });\n  for (let i = 0; i < (R.lg || 0); i++) { const n = grantLegend(); if (n) got.push(n); else R = { ...R, cr: (R.cr || 0) + 500 }; }\n  ACHD()[id] = { t: Date.now(), n: 1, got };\n  try { H.reward && H.reward(name, rewardTxt(R, got), R.cr || 0, R.tt ? [R.tt, TTL[R.tt]] : null); } catch (e) {}\n  achToast(name, rewardTxt(R, got), got.length);\n}\n// Vérifie tous les succès et objectifs Collector ; donne les récompenses nouvellement gagnées.\nfunction achCheck() {\n  try {\n    let any = 0;\n    ACHL.forEach(([id, n, , pr, R]) => { if (ACHD()[id]) return; const [a, b] = pr(); if (b > 0 && a >= b) { giveReward(id, n, R); any = 1; } });\n    COLL().forEach(o => { const id = 'col_' + o.tm; if (ACHD()[id] || !o.cs.length || o.have < o.cs.length) return; giveReward(id, 'Collector · ' + o.tm, o.legs.length ? {} : { cr: 800 }, o.legs); any = 1; });\n    // Panthéon peut se débloquer juste après une Légende gagnée\n    achSnap();\n    if (any) { bsSave(); setTimeout(achCheck, 50); boCount(); if (!$('bo').hidden && ['hub', 'coll'].includes(BS.view)) boRender(); }\n  } catch (e) { console.warn(e); }\n}\n// Photo des succès pour la Galerie de la carrière (affichée hors du jeu de cartes).\nfunction achSnap() {\n  const A = ACHD(), old = JSON.stringify(ST.snap || null);\n  ST.snap = {\n    ach: ACHL.map(([id, n, d, pr, R]) => { const [a, b] = pr(); return { id, n, d, a, b, ok: !!A[id], got: (A[id] && A[id].got) || [], cr: R.cr || 0, tt: R.tt ? 1 : 0, lg: R.lg ? 1 : 0 }; }),\n    col: COLL().map(o => ({ tm: o.tm, have: o.have, tot: o.cs.length, legs: o.legs.map(c => c.n), ok: !!A['col_' + o.tm] })),\n    legs: canon().filter(c => !c.ev).map(c => ({ n: c.n, tm: c.tm, pos: c.pos, has: !!BS.coll[c.k + '#5'] })),\n  };\n  if (JSON.stringify(ST.snap) != old) { try { H.snapped && H.snapped(); } catch (e) {} }\n}\nsetTimeout(() => { achCheck(); achSnap(); }, 700);\n// Pendant un duel : effets de gardien déclenchés et liens +10 du joueur.\nfunction achDuelTurn(E) {\n  const P = G.p[0];\n  if (E && E.e) TS().gk++;\n  if (P.bench.some(c => c.t == 'J' && whyOf(c, P.bench, P.gk).b >= 10)) TS().l10 = 1;\n  if (P.bench.length && P.bench.every(c => (c.r || 1) > 1)) G.nocl = (G.nocl || 0) + 1; else G.allcl = 1;\n}\nfunction achDuelEnd(w, why) {\n  const t = TS(); t.duels++;\n  if (w == 0) {\n    t.wins++;\n    if (scored(0) >= 3 && scored(1) == 0) t.w30 = 1;\n    if (/Mort subite/.test(why || '')) t.sud = 1;\n    if ((G.maxDef || 0) >= 2) t.cmb = 1;\n    if (G.nocl && !G.allcl) t.nocl = 1;\n  }\n  bsSave(); setTimeout(achCheck, 900);\n}\n// Petite annonce dans le jeu de cartes quand un succès tombe.\nfunction achToast(name, txt, leg) {\n  const d = document.createElement('div'); d.className = 'atoast' + (leg ? ' leg' : '');\n  d.style.bottom = 18 + document.querySelectorAll('.atoast').length * 70 + 'px';\n  d.innerHTML = `<b>🏆 ${name}</b><small>${txt}</small>`;\n  document.body.appendChild(d); setTimeout(() => d.classList.add('go'), 20); setTimeout(() => d.remove(), 5200);\n}\n\n/* =================== BOOSTERS (prototype) =================== */\n// Raretés de Galactik Manager : 1 Classique, 2 Chromatique, 3 Prismatique, + 4 Mythique (doré).\nconst RAR = { 1: 'Classique', 2: 'Chromatique', 3: 'Prismatique', 4: 'Mythique', 5: 'Légende' };\n// Cartes Légende : version exclusive des personnages canon, obtenue seulement par les succès et la collection (jamais en booster).\nconst LEGB = 5; // bonus de la version Légende sur les deux valeurs d'un joueur ; un gardien Légende active son effet avec un joueur de moins\nconst BNAME = { V: 'Victoire', N: 'Match nul', D: 'Défaite' };\n// Collection complète : joueurs, gardiens et tactiques ; rareté fixe par carte (provisoire).\n// Collection : chaque carte a ses raretés possibles. Joueurs chromatiques de Galactik Manager : Chromatique seulement ;\n// prismatiques : Prismatique seulement ; les autres : Classique ou Mythique. Plus la note générale est haute, plus la version Mythique sort.\nconst POOL = (() => {\n  const out = [];\n  ROSTER.forEach(r => { const c = mkCard(r); delete c.id; c.k = 'J:' + c.n; c.rs = r[5] == 'c' ? [2] : r[5] == 'p' ? [3] : [1, 4]; if (r[5] == 'c') c.lg = 1; out.push(c); });\n  TN.forEach(n => { const c = mkTac(n); delete c.id; c.k = 'T:' + n; c.o = 66; c.rs = [1, 4]; out.push(c); });\n  EVR.forEach(r => { const c = mkCard(r); delete c.id; c.k = 'J:' + c.n; c.rs = [5]; c.ev = 1; out.push(c); });\n  return out;\n})();\nconst MYTH = { V: .10, N: .06, D: .03 }, SPEC = { V: .45, N: .32, D: .2 };\nfunction rollCard(ty) {\n  const w = POOL.map(c => c.ev ? 0 : c.rs.length == 1 ? SPEC[ty] : 1), sum = w.reduce((s, x) => s + x, 0);\n  let x = Math.random() * sum, i = 0; while ((x -= w[i]) > 0) i++;\n  const c = POOL[i];\n  let r = c.rs[0];\n  if (c.rs.length > 1) r = Math.random() < MYTH[ty] * Math.min(1.6, Math.max(.15, (c.o - 55) / 20)) ? 4 : 1;\n  return { ...c, r };\n}\nfunction drawPack(ty) { return [0, 1, 2].map(() => rollCard(ty)).sort((a, b) => a.r - b.r); } // la plus rare en dernier\n// Taux observés de chaque rareté par booster (estimés une fois au chargement).\nconst ODDS = Object.fromEntries(['V', 'N', 'D'].map(ty => { const n = [0, 0, 0, 0, 0]; for (let i = 0; i < 6000; i++) n[rollCard(ty).r]++; return [ty, [1, 2, 3, 4].map(r => Math.round(n[r] / 60 * 10) / 10)]; }));\nconst BS = { stock: ST.stock, coll: ST.coll, view: 'packs' };\nfunction bsSave() { H.save(); }\nconst ckey = c => c.k + '#' + c.r;\nconst rsx = c => c.lg ? [...c.rs, 5] : c.rs; // raretés possibles, Légende comprise\nconst owned = c => rsx(c).reduce((s, r) => s + (BS.coll[c.k + '#' + r] || 0), 0);\nfunction boCount() { const n = BS.stock.V + BS.stock.N + BS.stock.D; $('boN').textContent = n || ''; }\n// rareté affichée : celle de la carte tirée, sinon la plus haute rareté possédée (les étoiles s'allument en conséquence)\nconst topOwned = d => Math.max(1, ...(d && d.rs ? rsx(d) : []).filter(r => BS.coll[d.k + '#' + r]));\nconst legUp = x => { if (x.r == 5 && x.t == 'J') { x.a += LEGB; x.d += LEGB; } return x; };\nconst asCard = c => legUp({ ...c, r: c.r || topOwned(c), id: 'c-' + c.k + '-' + Math.random().toString(36).slice(2, 6) });\n// Boosters dont l'illustration est fournie (les autres gardent le visuel généré)\nconst PKIMG = { V: 1, N: 1, D: 1 };\nfunction packHTML(ty, cnt, big) {\n  return `<div class=\"pk ${ty}${PKIMG[ty] ? ' img' : ''}${cnt === 0 ? ' empty' : ''}\" data-ty=\"${ty}\" role=\"button\" aria-label=\"Booster ${BNAME[ty]}\">\n    <div class=\"pf\"></div><div class=\"crimp t\"></div><div class=\"crimp b\"></div>\n    <div class=\"lab\"><span class=\"em\"><i>GC</i></span><b>${BNAME[ty]}</b><small>Booster · 3 cartes</small></div>\n    ${big ? '' : `<span class=\"cnt\">${cnt}</span>`}</div>`;\n}\nfunction freeUI() { if (G && G.phase == 'play') { if (!G.modalLock) closeModal(); return true; } if (G) G.modalLock = false; if (ST.deckStart) closeModal(); return true; }\nfunction boOpen() { if (G && G.phase == 'play' && G.modalLock && !$('mo').hidden) return; freeUI(); BS.view = 'packs'; $('bo').hidden = false; boRender(); }\nfunction boClose() { $('bo').hidden = true; boCount(); }\nfunction boHead(title) {\n  const tab = (v, l) => `<button class=\"${BS.view == v ? 'on' : ''}\" onclick=\"BS.view='${v}';DK.ed=null;boRender()\">${l}</button>`;\n  return `<div class=\"boh\">${title && title != 'Galactik Cartes' ? `<h2>${title}</h2>` : ''}<div class=\"tabs2\">${tab('hub', 'Accueil')}${tab('packs', 'Boosters' + (tStock() ? ` <span class=\"bn\">${tStock()}</span>` : ''))}${tab('coll', 'Collection')}${tab('decks', 'Mes decks')}<button onclick=\"H.gal && H.gal()\">Succès${achNew() ? ` <span class=\"bn\">${achNew()}</span>` : ''}</button><button onclick=\"rulesTour(0)\">Règles</button></div><div class=\"sp\">${G && G.phase == 'play' ? '<button class=\"p\" onclick=\"boClose()\">Reprendre le duel</button>' : ''}</div></div>`;\n}\nconst tStock = () => BS.stock.V + BS.stock.N + BS.stock.D;\n// Accueil du jeu de cartes : choix du deck et lancement d'un duel, boosters, collection, decks.\nfunction hubRender() {\n  if (!hubRender.ck) { hubRender.ck = 1; setTimeout(achCheck, 600); }\n  const ok = ST.decks.filter(d => deckCheck(d).ok);\n  if (!ok.some(d => d.id == ST.active) && ok.length) ST.active = ok[0].id;\n  const act = ST.decks.find(d => d.id == ST.active), gk = act && byK(act.gk) ? Object.assign(mkCard(rowOf(nameOf(act.gk))), { r: topOwned(byK(act.gk)) }) : null;\n  const sp = { lent: 1.6, normal: 1, rapide: .45 }, curS = Object.keys(sp).find(k => sp[k] == SPEED) || 'normal';\n  const own = POOL.filter(c => owned(c)).length, n = tStock(), playing = G && G.phase == 'play';\n  $('bow').innerHTML = boHead('Galactik Cartes') + `<div class=\"hub\">\n  <div class=\"hc hc1\"><div class=\"hct\"><b>Jouer un duel</b><span>Contre l’IA, avec le deck de votre choix. 3 buts pour gagner.</span></div>\n    ${playing ? `<div class=\"hcal\">Un duel est en cours : ${scored(0)} – ${scored(1)}, tour ${G.turn}.</div>` : ''}\n    <div class=\"zl\" style=\"text-align:left\">Votre deck</div>\n    <div class=\"hdk\">${ST.decks.map(d => { const v = deckCheck(d); return `<button class=\"hdb ${d.id == ST.active ? 'on' : ''}\" ${v.ok ? `onclick=\"ST.active=${d.id};bsSave();hubRender()\"` : 'disabled'}><b>${d.name}</b><small>${v.ok ? 'Gardien : ' + nameOf(d.gk) : 'Incomplet'}</small></button>`; }).join('')}</div>\n    ${gk ? `<div class=\"hgk\"><div style=\"--cw:74px\">${cardHTML(gk)}</div><div><b>${gk.n}</b><small>${effText(gk)}</small></div></div>` : ''}\n    <div class=\"zl\" style=\"text-align:left\">Vitesse des animations</div><div class=\"opts\" id=\"hSp\">${Object.keys(sp).map(k => `<button class=\"ghost ${k == curS ? 'on' : ''}\" data-v=\"${k}\">${k[0].toUpperCase() + k.slice(1)}</button>`).join('')}</div>\n    <div class=\"row\" style=\"justify-content:flex-start\">${playing ? '<button class=\"ghost\" onclick=\"boClose()\">Reprendre le duel</button>' : ''}<button class=\"p\" ${ok.length ? '' : 'disabled'} onclick=\"newDuel()\">${playing ? 'Nouveau duel' : 'Lancer le duel'}</button></div></div>\n  <div class=\"hc ${n ? 'glow' : ''}\"><div class=\"hct\"><b>Boosters</b><span>${n ? `${n} booster${n > 1 ? 's' : ''} à ouvrir` : 'Gagnez-en en jouant les matchs de votre club.'}</span></div>\n    <div class=\"hpk\">${['V', 'N', 'D'].map(ty => `<div class=\"mini ${ty}${BS.stock[ty] ? '' : ' off'}\"><b>${BNAME[ty]}</b><span>${BS.stock[ty]}</span></div>`).join('')}</div>\n    <div class=\"row\" style=\"justify-content:flex-start\"><button class=\"${n ? 'p' : ''}\" onclick=\"BS.view='packs';boRender()\">Ouvrir mes boosters</button></div></div>\n  <div class=\"hc\"><div class=\"hct\"><b>Collection</b><span>${own} / ${POOL.length} cartes différentes</span></div>\n    <div class=\"hst\">${[5, 4, 3, 2, 1].map(r => `<div><b>${POOL.filter(c => BS.coll[c.k + '#' + r]).length}</b><small>${RAR[r]}</small></div>`).join('')}</div>\n    <div class=\"row\" style=\"justify-content:flex-start\"><button onclick=\"BS.view='coll';boRender()\">Voir la collection</button></div></div>\n  <div class=\"hc\"><div class=\"hct\"><b>Mes decks</b><span>${ST.decks.length} deck${ST.decks.length > 1 ? 's' : ''} · deck actif : ${act ? act.name : '—'}</span></div>\n    <div class=\"row\" style=\"justify-content:flex-start\"><button onclick=\"BS.view='decks';DK.ed=null;boRender()\">Gérer mes decks</button><button class=\"ghost\" onclick=\"BS.view='decks';newDeck()\">Nouveau deck</button></div></div>\n  </div>`;\n  $('hSp').onclick = e => { const b = e.target.closest('button'); if (!b) return; SPEED = sp[b.dataset.v]; [...$('hSp').children].forEach(x => x.classList.toggle('on', x == b)); };\n}\nfunction goHub() { freeUI(); BS.view = 'hub'; DK.ed = null; $('bo').hidden = false; boRender(); }\nfunction newDuel() { if (G && G.phase == 'play') { G = null; } resetBoard(); $('bo').hidden = true; coin(); }\nfunction boRender() {\n  const w = $('bow'); boCount();\n  if (BS.view == 'hub') return hubRender();\n  if (BS.view == 'coll') return collRender();\n  if (BS.view == 'decks') return decksRender();\n  const odds = ty => ODDS[ty].map((v, i) => `${RAR[i + 1]} <b>${v} %</b>`).join('<br>') + '<br><span style=\"opacity:.7\">(par carte, environ)</span>';\n  w.innerHTML = boHead('Boosters') + `<p class=\"hint\" style=\"text-align:left\">Touchez un booster pour l’ouvrir. Votre club en gagne un à la fin de chaque match : son contenu dépend du résultat.</p>\n  <div class=\"packs\">${['V', 'N', 'D'].map(ty => `<div>${packHTML(ty, BS.stock[ty])}<div class=\"odds\">${odds(ty)}</div></div>`).join('')}</div>\n`;  w.querySelectorAll('.packs .pk').forEach(el => el.onclick = () => { const ty = el.dataset.ty; if (BS.stock[ty] > 0) openPack(ty); });\n}\nasync function openPack(ty) {\n  BS.stock[ty]--; bsSave(); boCount();\n  const cards = drawPack(ty).map(asCard);\n  const w = $('bow');\n  w.innerHTML = `<div class=\"boh\"><h2>Booster ${BNAME[ty]}</h2></div><div class=\"stage\" id=\"stg\"><div class=\"flash\" id=\"fls\"></div>${packHTML(ty, 0, true)}<div class=\"hint\" id=\"hnt\">Touchez le booster pour le déchirer</div></div>`;\n  const pk = w.querySelector('.stage .pk');\n  await new Promise(r => pk.onclick = r);\n  pk.onclick = null; $('hnt').textContent = '';\n  pk.classList.add('shake'); await new Promise(r => setTimeout(r, 560));\n  pk.classList.remove('shake'); pk.classList.add('open', 'gone'); $('fls').classList.add('go');\n  await new Promise(r => setTimeout(r, 900));\n  const seen = []; cards.forEach(c => { seen.push(owned(c) > 0); BS.coll[ckey(c)] = (BS.coll[ckey(c)] || 0) + 1; }); bsSave();\n  TS().packs++; if (cards.some(c => c.r == 4)) TS().myth = 1; setTimeout(achCheck, 2500);\n  $('stg').innerHTML = `<div class=\"halo\" id=\"hal\"></div><div class=\"reveal\">${cards.map((c, i) => `<div class=\"rc r${c.r}\" style=\"animation-delay:${i * 160}ms\" data-i=\"${i}\">\n      <span class=\"rrw\"><span class=\"rr c${c.r}\">${RAR[c.r]}</span></span>\n      <div class=\"fl\"><div class=\"fc\"><div class=\"bk\"><div>GC</div></div></div><div class=\"fc f\">${cardHTML(c).replace('class=\"card ', `class=\"card R${c.r} `)}</div></div>\n      <span class=\"tag ${seen[i] ? 'dup' : 'new'}\">${seen[i] ? 'DOUBLON' : 'NOUVELLE'}</span></div>`).join('')}</div>\n    <div class=\"hint\" id=\"hnt\">Touchez chaque carte pour la retourner</div>\n    <div class=\"row\" style=\"justify-content:center\"><button id=\"rvAll\">Tout révéler</button></div>`;\n  let left = cards.length;\n  const flip = el => {\n    if (el.classList.contains('up')) return;\n    el.classList.add('up'); left--;\n    const r = +el.className.match(/r(\\d)/)[1];\n    if (r >= 2) setTimeout(() => rareFx(el, r), 330);\n    if (!left) { $('hnt').textContent = ''; $('rvAll').outerHTML = `<button class=\"ghost\" onclick=\"boRender()\">Mes boosters</button><button onclick=\"BS.view='coll';boRender()\">Voir la collection</button>`; }\n  };\n  $('stg').querySelectorAll('.rc').forEach(el => el.querySelector('.fl').onclick = () => flip(el));\n  $('rvAll').onclick = () => $('stg').querySelectorAll('.rc').forEach((el, i) => setTimeout(() => flip(el), i * 450));\n}\nconst RCOL = { 2: ['#ff4fa3', '#ffd23f', '#46e08a', '#33e0ff', '#9b6bff'], 3: ['#ffffff', '#c9b8ff', '#a8e6ff', '#ffc2e0', '#fff3b0'], 4: ['#fff6c8', '#ffd23f', '#e8b923', '#ffe680', '#ffffff'] };\nfunction rareFx(el, r) { // halo de la couleur de la rareté, éclairs dans tout l'écran, particules\n  const h = $('hal'); if (h) { h.className = 'halo h' + r; void h.offsetWidth; h.classList.add('go'); }\n  // pas d'éclairs : halo, tremblement (prismatique et mythique) et particules\n  if (r >= 3) { const st = $('stg'); st.classList.remove('shk'); void st.offsetWidth; st.classList.add('shk'); }\n  burst(el, r);\n}\nfunction burst(el, r) {\n  const cols = RCOL[r];\n  for (let i = 0; i < (r == 4 ? 40 : r == 3 ? 26 : 16); i++) {\n    const b = document.createElement('span'), a = Math.random() * Math.PI * 2, d = 70 + Math.random() * (r == 4 ? 140 : 80);\n    b.className = 'burst'; b.style.background = cols[i % cols.length];\n    b.style.setProperty('--x', Math.cos(a) * d + 'px'); b.style.setProperty('--y', Math.sin(a) * d + 'px');\n    el.appendChild(b); setTimeout(() => b.remove(), 950);\n  }\n}\nfunction collRender() {\n  const own = POOL.filter(c => owned(c)), dup = POOL.reduce((s, c) => s + Math.max(0, owned(c) - 1), 0);\n  const top = c => Math.max(0, ...rsx(c).filter(r => BS.coll[c.k + '#' + r]));\n  const cnt = r => POOL.filter(c => BS.coll[c.k + '#' + r]).length, tot = r => POOL.filter(c => rsx(c).includes(r)).length;\n  const sorted = POOL.slice().sort((a, b) => (!!owned(b) - !!owned(a)) || top(b) - top(a) || a.n.localeCompare(b.n));\n  $('bow').innerHTML = boHead('Collection') + `<div class=\"stats\"><div><b>${own.length} / ${POOL.length}</b>cartes différentes</div><div><b>${dup}</b>doublons (revente à venir)</div>${[5, 4, 3, 2, 1].map(r => `<div><b>${cnt(r)} / ${tot(r)}</b>${RAR[r]}</div>`).join('')}</div>\n  <div class=\"coll\">${sorted.map(c => { const n = owned(c), r = top(c); return `<div class=\"it${n ? '' : ' miss'}\">${n ? cardHTML(asCard(c)).replace('class=\"card ', `class=\"card R${r} `) : cardHTML(asCard(c), { back: true })}<span class=\"x\">${n ? rsx(c).filter(q => BS.coll[c.k + '#' + q]).map(q => RAR[q] + (BS.coll[c.k + '#' + q] > 1 ? ` <b>×${BS.coll[c.k + '#' + q]}</b>` : '')).join(' · ') : '???'}</span></div>`; }).join('')}</div>\n  <div class=\"row\" style=\"justify-content:flex-start;align-items:center\"><button onclick=\"sellDups(this)\" ${sellPlan().tot ? '' : 'disabled'}>Vendre les doublons (${sellPlan().tot} crédits)</button><span class=\"hint\">Garde au moins 1 exemplaire de chaque carte et ceux utilisés dans vos decks. Prix provisoires : ${[1, 2, 3, 4].map(r => RAR[r] + ' ' + PRICE[r]).join(' · ')} crédits.</span></div>`;\n}\nfunction sellPlan() { // doublons vendables : on garde au moins 1 exemplaire (le plus rare) et ceux utilisés dans les decks\n  const out = []; let tot = 0;\n  POOL.forEach(c => {\n    let extra = owned(c) - Math.max(1, usedMax(c.k)); if (extra <= 0) return;\n    const rs = c.rs.filter(r => BS.coll[c.k + '#' + r]).sort((a, b) => a - b), top = rs[rs.length - 1];\n    for (const r of rs) { let n = BS.coll[c.k + '#' + r] - (r == top ? 1 : 0); while (n > 0 && extra > 0) { out.push(c.k + '#' + r); tot += PRICE[r]; n--; extra--; } }\n  });\n  return { out, tot };\n}\nfunction sellDups(btn) {\n  const p = sellPlan(); if (!p.tot) return;\n  if (!btn.dataset.c) { btn.dataset.c = 1; btn.textContent = `Confirmer la vente : ${p.out.length} cartes pour ${p.tot} crédits`; return; }\n  p.out.forEach(k => { BS.coll[k]--; if (BS.coll[k] <= 0) delete BS.coll[k]; });\n  H.sell(p.tot, p.out.length + ' doublons vendus'); boRender(); achCheck();\n}\n$('bBo').onclick = boOpen;\nboCount();\n\n/* =================== DECKS =================== */\nconst PRICE = { 1: 10, 2: 40, 3: 80, 4: 150 }; // prix de revente provisoires (crédits)\nconst DK = { ed: null, f: 'J' };\nconst byK = k => POOL.find(c => c.k == k);\nconst nameOf = k => (byK(k) || {}).n || k;\nfunction deckCheck(d) {\n  const ks = Object.keys(d.cards).filter(k => d.cards[k] > 0), n = ks.reduce((s, k) => s + d.cards[k], 0);\n  const nj = ks.filter(k => (byK(k) || {}).t == 'J').reduce((s, k) => s + d.cards[k], 0);\n  const err = [];\n  if (!d.gk || !owned(byK(d.gk) || { rs: [], k: '' })) err.push('choisissez un gardien');\n  if (n != 40) err.push(`${n}/40 cartes`);\n  if (nj < 20) err.push(`${nj}/20 joueurs minimum`);\n  ks.forEach(k => { if (d.cards[k] > 3) err.push(`${nameOf(k)} : 3 exemplaires maximum`); if (d.cards[k] > owned(byK(k))) err.push(`${nameOf(k)} : pas assez d’exemplaires`); });\n  return { ok: !err.length, err, n, nj };\n}\nconst usedMax = k => Math.max(0, ...ST.decks.map(d => d.cards[k] || 0), ...ST.decks.map(d => d.gk == k ? 1 : 0));\nfunction starterDeck(tm) {\n  const cards = {};\n  starterRows(tm).forEach(r => cards['J:' + r[0]] = (cards['J:' + r[0]] || 0) + 1);\n  TSTART.forEach(n => cards['T:' + n] = (cards['T:' + n] || 0) + 1);\n  const gk = ROSTER.filter(r => r[1] == 'GK' && r[2] == tm).sort((x, y) => x[4] - y[4])[0];\n  return { cards, gk: 'J:' + gk[0] };\n}\nfunction decksRender() {\n  if (DK.ed) return deckEdit();\n  const act = ST.active;\n  $('bow').innerHTML = boHead('Mes decks') + `<p class=\"hint\" style=\"text-align:left\">Un deck valide contient 40 cartes plus un gardien, dont au moins 20 cartes Joueur, et 3 exemplaires au maximum d’une même carte (toutes raretés confondues). Le deck actif est utilisé pour les duels.</p>\n  <div class=\"dkl\">${ST.decks.map(d => { const v = deckCheck(d); return `<div class=\"dkc${d.id == act ? ' on' : ''}\"><div><b>${d.name}</b> ${d.id == act ? '<span class=\"tagA\">ACTIF</span>' : ''}<small>${v.ok ? 'Valide · gardien ' + nameOf(d.gk) : 'Incomplet : ' + v.err.slice(0, 2).join(', ')}</small></div><div class=\"dkb\">${v.ok && d.id != act ? `<button onclick=\"ST.active=${d.id};bsSave();boRender()\">Utiliser</button>` : ''}<button onclick=\"DK.ed=JSON.parse(JSON.stringify(ST.decks.find(x=>x.id==${d.id})));boRender()\">Modifier</button>${ST.decks.length > 1 && d.id != act ? `<button class=\"ghost\" onclick=\"if(this.dataset.c){ST.decks=ST.decks.filter(x=>x.id!=${d.id});bsSave();boRender()}else{this.dataset.c=1;this.textContent='Confirmer'}\">Supprimer</button>` : ''}</div></div>`; }).join('')}</div>\n  <div class=\"row\" style=\"justify-content:flex-start\"><button onclick=\"newDeck()\">Nouveau deck</button></div>`;\n}\nfunction newDeck() {\n  const src = ST.decks.find(d => d.id == ST.active) || ST.decks[0], id = Math.max(0, ...ST.decks.map(d => d.id)) + 1;\n  DK.ed = { id, name: 'Deck ' + id, gk: src ? src.gk : null, cards: src ? { ...src.cards } : {}, isNew: 1 };\n  boRender();\n}\nfunction deckEdit() {\n  const d = DK.ed, v = deckCheck(d);\n  const own = POOL.filter(c => owned(c));\n  const list = own.filter(c => DK.f == 'G' ? c.t == 'G' : c.t == DK.f).sort((a, b) => (a.tm || '').localeCompare(b.tm || '') || a.n.localeCompare(b.n));\n  const inDeck = Object.keys(d.cards).filter(k => d.cards[k] > 0).map(byK).filter(Boolean).sort((a, b) => (a.t > b.t ? 1 : a.t < b.t ? -1 : 0) || a.n.localeCompare(b.n));\n  const cell = c => { const n = d.cards[c.k] || 0, max = Math.min(3, owned(c)); return c.t == 'G'\n      ? `<div class=\"dki${d.gk == c.k ? ' sel' : ''}\" onclick=\"DK.ed.gk='${c.k}';boRender()\">${cardHTML(asCard(c))}<span>${d.gk == c.k ? 'Gardien choisi' : 'Choisir'}</span></div>`\n      : `<div class=\"dki${n ? ' sel' : ''}\">${cardHTML(asCard(c))}<span><button ${n >= max ? 'disabled' : ''} onclick=\"DK.ed.cards['${c.k}']=(DK.ed.cards['${c.k}']||0)+1;boRender()\">+</button> ${n}/${max} <button ${n ? '' : 'disabled'} onclick=\"DK.ed.cards['${c.k}']--;boRender()\">−</button></span></div>`; };\n  $('bow').innerHTML = boHead('Mes decks') + `<div class=\"dkh\"><input id=\"dkName\" value=\"${d.name.replace(/\"/g, '&quot;')}\" maxlength=\"24\" aria-label=\"Nom du deck\" oninput=\"DK.ed.name=this.value\">\n    <span class=\"dks2 ${v.ok ? 'ok' : ''}\">${v.n}/40 cartes · ${v.nj} joueurs · gardien : ${d.gk ? nameOf(d.gk) : '—'}</span>\n    <button class=\"ghost\" onclick=\"DK.ed=null;boRender()\">Annuler</button><button onclick=\"saveDeck()\">Enregistrer</button></div>\n    ${v.ok ? '' : `<p class=\"hint\" style=\"text-align:left;color:#ffb3c1\">${v.err.slice(0, 4).join(' · ')}</p>`}\n    <div class=\"dkg\"><div><div class=\"tabs2\">${[['J', 'Joueurs'], ['T', 'Tactiques'], ['G', 'Gardiens']].map(([k, l]) => `<button class=\"${DK.f == k ? 'on' : ''}\" onclick=\"DK.f='${k}';boRender()\">${l}</button>`).join('')}</div>\n    <div class=\"coll dkc2\">${list.map(cell).join('') || '<p class=\"hint\">Aucune carte de ce type dans votre collection.</p>'}</div></div>\n    <div><b class=\"zl\" style=\"text-align:left;display:block;margin-bottom:6px\">Dans le deck</b><div class=\"dkls\">${inDeck.map(c => `<div><span>${d.cards[c.k]}×</span>${c.n}<small>${c.t == 'J' ? c.pos + ' · ' + c.tm : 'Tactique'}</small><button onclick=\"DK.ed.cards['${c.k}']--;boRender()\">−</button></div>`).join('') || '<p class=\"hint\">Deck vide.</p>'}</div></div></div>`;\n}\nfunction saveDeck() {\n  const d = DK.ed; delete d.isNew;\n  Object.keys(d.cards).forEach(k => { if (!(d.cards[k] > 0)) delete d.cards[k]; });\n  const i = ST.decks.findIndex(x => x.id == d.id);\n  if (i >= 0) ST.decks[i] = d; else ST.decks.push(d);\n  if (!deckCheck(ST.decks.find(x => x.id == ST.active) || { cards: {} }).ok && deckCheck(d).ok) ST.active = d.id;\n  DK.ed = null; bsSave(); boRender();\n  setTimeout(achCheck, 300);\n}\n// Deck de départ : choisi une seule fois, définitivement.\nfunction starterScreen() {\n  let pick = null;\n  const draw = () => modal(`<h2>Choisissez votre deck de départ</h2><p>Bienvenue dans Galactik Cartes ! Choisissez l’équipe de votre premier deck : ses joueurs, son gardien remplaçant et 15 tactiques de base. <b>Ce choix est définitif.</b> Vous pourrez ensuite créer d’autres decks avec les cartes de vos boosters.</p>\n  <div class=\"opts dks\" id=\"oDk\">${TEAMS.map(([tm]) => { const g = mkStarter(tm, 0).gk; return `<button class=\"ghost dk ${tm == pick ? 'on' : ''}\" data-v=\"${tm}\"><b>${tm}</b><small>${g.n} · ${effText(g, true)}</small></button>`; }).join('')}</div>\n  <div class=\"row\"><button class=\"ghost\" onclick=\"H.close()\">Plus tard</button><button id=\"go\" ${pick ? '' : 'disabled'}>${pick ? 'Prendre le deck ' + pick + ' (définitif)' : 'Choisissez une équipe'}</button></div>`);\n  draw();\n  const bind = () => {\n    $('oDk').onclick = e => { const b = e.target.closest('button'); if (!b) return; pick = b.dataset.v; draw(); bind(); };\n    $('go').onclick = () => {\n      if (!pick) return;\n      if (!$('go').dataset.c) { $('go').dataset.c = 1; $('go').textContent = 'Confirmer : ' + pick + ' pour toute la carrière'; return; }\n      const sd = starterDeck(pick);\n      Object.keys(sd.cards).forEach(k => { const c = byK(k); const r = c.rs.length == 1 ? c.rs[0] : 1; BS.coll[k + '#' + r] = (BS.coll[k + '#' + r] || 0) + sd.cards[k]; });\n      { const c = byK(sd.gk); const r = c.rs.length == 1 ? c.rs[0] : 1; BS.coll[sd.gk + '#' + r] = (BS.coll[sd.gk + '#' + r] || 0) + 1; }\n      ST.deckStart = pick; ST.decks = [{ id: 1, name: 'Deck ' + pick, gk: sd.gk, cards: sd.cards }]; ST.active = 1; bsSave();\n      G = null; closeModal(); startScreen();\n    };\n  };\n  bind();\n}\n// Construit un joueur (main, deck, gardien) à partir d'un deck enregistré.\nfunction deckPlayer(name, d) {\n  const deck = [];\n  const topR = c => Math.max(1, ...c.rs.filter(r => BS.coll[c.k + '#' + r]));\n  Object.keys(d.cards).forEach(k => { const c = byK(k), nl = BS.coll[k + '#5'] || 0; for (let i = 0; i < d.cards[k]; i++) { const x = c.t == 'T' ? mkTac(c.n) : mkCard(rowOf(c.n)); x.r = i < nl ? 5 : topR(c); deck.push(legUp(x)); } });\n  const gk = mkCard(rowOf(nameOf(d.gk))); gk.r = BS.coll[d.gk + '#5'] ? 5 : topR(byK(d.gk));\n  return { name, deck: shuffle(deck), gk, tms: [d.name], hand: [], disc: [], goals: [], bench: [], hs: 5, pd: 0 };\n}\n$('tDuel').onclick = () => goHub();\n$('tColl').onclick = () => { if (G && G.phase == 'play' && G.modalLock && !$('mo').hidden) return; freeUI(); BS.view = 'coll'; $('bo').hidden = false; boRender(); };\n$('tDecks').onclick = () => { if (G && G.phase == 'play' && G.modalLock && !$('mo').hidden) return; freeUI(); BS.view = 'decks'; DK.ed = null; $('bo').hidden = false; boRender(); };\n// Couleurs du club du joueur, reprises de Galactik Manager\nfunction syncTheme() {\n  try {\n    const cs = parent.getComputedStyle(parent.document.body), g = k => cs.getPropertyValue(k).trim(), r = document.documentElement.style;\n    const m = { '--panel': g('--card'), '--bd': g('--bd'), '--tx': g('--tx'), '--mu': g('--mu'), '--mu2': g('--mu'), '--peri': g('--ac'), '--onac': g('--onac'), '--side': g('--sb'), '--deep': g('--bg'), '--ac2': g('--ac2') };\n    for (const k in m) if (m[k]) r.setProperty(k, m[k]);\n    if (g('--bd')) r.setProperty('--bd2', `color-mix(in srgb, ${g('--bd')} 45%, transparent)`);\n    if (cs.backgroundImage && cs.backgroundImage != 'none') document.body.style.backgroundImage = cs.backgroundImage;\n    if (g('--bg')) document.body.style.backgroundColor = g('--bg');\n  } catch (e) {}\n}\n// Aperçu agrandi d'une carte au survol (ou par appui long sur écran tactile)\nconst ZP = document.createElement('div'); ZP.id = 'zoomp'; document.body.appendChild(ZP);\nlet zT = null, zSrc = null, zLong = false;\nfunction zHide() { clearTimeout(zT); zSrc = null; ZP.classList.remove('on'); }\nfunction zShow(el) {\n  if (!el || el.classList.contains('back') || el.closest('#zoomp') || el.closest('.opp-hand')) return zHide();\n  zSrc = el;\n  const cl = el.cloneNode(true); cl.removeAttribute('data-id'); cl.classList.remove('sel', 'flip', 'lkpop'); cl.removeAttribute('title');\n  cl.querySelectorAll('.pop').forEach(x => x.remove());\n  ZP.innerHTML = ''; ZP.appendChild(cl);\n  // toujours centré dans la zone du jeu de cartes\n  const w = ZP.offsetWidth, hh = ZP.offsetHeight, x = Math.max(0, (innerWidth - w) / 2), y = Math.max(0, (innerHeight - hh) / 2);\n  ZP.style.left = x + 'px'; ZP.style.top = y + 'px'; ZP.classList.add('on');\n}\ndocument.addEventListener('mouseover', e => {\n  if (e.pointerType == 'touch') return;\n  const el = e.target.closest('.card');\n  if (el === zSrc) return;\n  clearTimeout(zT);\n  if (!el) return zHide();\n  zT = setTimeout(() => zShow(el), 140);\n});\ndocument.addEventListener('mouseleave', zHide);\ndocument.addEventListener('scroll', zHide, true);\ndocument.addEventListener('touchstart', e => {\n  const el = e.target.closest('.card'); zLong = false; clearTimeout(zT);\n  if (el) zT = setTimeout(() => { zLong = true; zShow(el); }, 420);\n}, { passive: true });\ndocument.addEventListener('touchmove', () => { clearTimeout(zT); if (zLong) zHide(); }, { passive: true });\ndocument.addEventListener('touchend', e => { clearTimeout(zT); if (zLong) { e.preventDefault(); zLong = false; setTimeout(zHide, 60); } });\nsyncTheme();\nif (!ST.deckStart) starterScreen();\nelse goHub();\n</script>\n</body></html>\n";
